                    local dx, dy = 0, 0
                    if focusBounds then
                        dx = bounds.x + bounds.w / 2 - focusBounds.x - focusBounds.w / 2
                        dy = bounds.y + bounds.h / 2 - focusBounds.y - focusBounds.h / 2
