    end)
    self.selectBar.Size = UDim2.fromScale(1, 1)
end

function Onboarding:_describe(text)
    self.description.Text = text
    local width = self.descriptionWidth
    if not width then return end
    if width == self.measuredDescriptionWidth and text == self.measuredDescription then return end
    self.measuredDescriptionWidth, self.measuredDescription = width, text
    local textService = self.services.TextService
    local ok, measured = pcall(function()
        return textService:GetTextSize(text, T.body, F.body, Vector2.new(width, 10000)).Y
    end)
    local height = ok and type(measured) == "number" and measured >= 0 and measured < 10000 and math.ceil(measured) + 4
    if not height then
        local lines, used, capacity = 1, 0, math.max(1, math.floor(width / (T.body * .55)))
        for word in text:gmatch("%S+") do
            if used > 0 and used + #word + 1 > capacity then lines, used = lines + 1, 0 end
            used = used + #word + 1
        end
        height = lines * (T.body + 4)
    end
    self.description.Size = UDim2.fromOffset(width, height)
    self.instructions.CanvasSize = UDim2.fromOffset(0, height)
end

function Onboarding:_completeLesson()
    local lesson = self.lesson
    if not self.lessonComplete and lesson.done then
        self.lessonComplete = true
        self:_describe(lesson.done)
        self.description.TextColor3 = C.cyan
    end
end

function Onboarding:_drawTools()
    local id = self.lesson.id
    self.slider.Visible = id == "resize"
    self.angleSlider.Visible = id == "rotate"
    self.opacitySlider.Visible, self.scopeButton.Visible = id == "opacity", id == "opacity"
    self.resetButton.Visible = id == "reset"
    self.layers.Visible = id == "layers" and not self.layerPicker
    self.chooseOverlay.Visible, self.chooseJump.Visible = self.layerPicker == true, self.layerPicker == true
    self.multi.Visible, self.group.Visible = id == "group", id == "group"
    for scope, button in pairs(self.selectionScopeButtons) do
        button.Visible = id == "scope"
        local active = self.scopeMode == scope
        button.BackgroundColor3, button.TextColor3 = active and C.selected or C.raised, active and C.cyan or C.text
    end
    self.selectBar.Visible = id == "compatibility"
end

function Onboarding:_showLayers(hits)
    if self.lesson.id ~= "layers" or #hits < 2 then return false end
    self.layerPicker = true
    self:_describe("Choose the control you want to edit.")
    self:_drawTools()
    return true
end

local function selected(keys, value)
    for index, key in ipairs(keys) do if key == value then return index end end
end

function Onboarding:_scopeComplete()
    local seen = self.scopeSeen
    if seen.whole and seen.layer and seen.container and self.scopeResized then self:_completeLesson() end
end

function Onboarding:_setPracticeScope(scope)
    if self.scopeMode ~= scope then
        self.input:cancel()
        self.scopeMode = scope
        self.app.selection = {}
    end
    if not self.lessonComplete then
        local hints = {
            whole = "Tap an ability. The large outline includes its number, icon, label, and decoration. Then pinch to resize them together.",
            layer = "Tap a number, icon, or label. Drag the small outline to adjust just that layer.",
            container = "Tap anywhere on the bar. Drag inside the outer outline to move all three abilities together.",
        }
        self:_describe(hints[scope])
    end
    self:_drawTools()
    self:_drawTargets()
end

function Onboarding:_select(key, additive)
    if additive then
        local index = selected(self.app.selection, key)
        if index then table.remove(self.app.selection, index) else self.app.selection[#self.app.selection + 1] = key end
    else self.app.selection = key and {key} or {} end
    if key == "Jump" and self.lesson.id == "select" then self:_completeLesson() end
    local target = self.targets[key]
    if target and target.scope and self.lesson.id == "scope" then
        self.scopeSeen[target.scope] = true
        self:_scopeComplete()
    elseif target and self.lesson.id == "compatibility" and not self.lessonComplete then
        self:_describe(key == "AbilityBar" and "Drag the bar to an open spot. All abilities will keep their slots." or managedHelp)
    end
    self:_drawTargets()
end

function Onboarding:_sizeInfo(rect)
    local target, canvas = rect or self.rects.Jump, self.canvasRect
    if not target or not canvas then return nil end
    local maximum = math.min(canvas.w - 12, canvas.h - 8)
    if maximum <= 38 then return nil end
    return {scale = target.w, minimum = 38, maximum = maximum, size = target}
end

function Onboarding:_abilityHits(x, y)
    local bar = self.targets.AbilityBar
    local barHit = Coordinates.contains(self.rects.AbilityBar, x, y)
    for index in ipairs(abilityNames) do
        local ability = "Ability" .. index
        if self.scopeMode ~= "layer" and Coordinates.contains(self.rects[ability], x, y) then
            local target = self.scopeMode == "container" and bar or self.targets[ability]
            return {target}, target
        end
        for _, part in ipairs(abilityParts) do
            local key = ability .. part
            if Coordinates.contains(self.rects[key], x, y) then
                local target = self.scopeMode == "container" and bar or self.targets[self.scopeMode == "layer" and key or ability]
                return {target}, target
            end
        end
    end
    if barHit and self.scopeMode == "container" then return {bar}, bar end
    return {}, false
end

function Onboarding:_drawTargets()
    local canvas = self.canvasRect
    if not canvas then return end
    local keys = self.app.selection
    local focused = self.targets[keys[1]]
    self.padTitle.Text = focused and focused.scope and (focused.name .. " · " .. scopeNames[focused.scope]) or "Practice canvas"
    for key, target in pairs(self.targets) do
        local rect = self.rects[key]
        if target.object.Visible ~= (rect ~= nil) then target.object.Visible = rect ~= nil end
        if rect then
            local origin = target.parentKey and self.rects[target.parentKey] or canvas
            target.object.Position = UDim2.fromOffset(rect.x - origin.x, rect.y - origin.y)
            target.object.Size = UDim2.fromOffset(rect.w, rect.h)
            local active = selected(keys, key)
            target.edge.Color = active and C.cyan or C.border
            if target.scope then
                target.edge.Transparency = active and 0 or (target.scope == "layer" and 1 or .4)
                if target.iconScale then target.iconScale.Scale = math.max(.55, math.min(1.65, math.min(rect.w, rect.h) / 22)) end
            else
                target.object.Rotation = key == "Jump" and self.angle or 0
                target.object.BackgroundTransparency = key == "Jump" and 1 - self.opacity / 100 or 0
                target.text.TextTransparency = key == "Jump" and self.practiceUI.opacityScope == "contents" and 1 - self.opacity / 100 or 0
            end
        end
    end
    local jump = self.rects.Jump
    self.overlay.Visible = self.lesson.id == "layers" and jump ~= nil
    if self.overlay.Visible then
        self.overlay.Position = UDim2.fromOffset(jump.x - canvas.x - 12, jump.y - canvas.y - 8)
        self.overlay.Size = UDim2.fromOffset(jump.w + 24, jump.h + 16)
    end
    local resize = self.lesson.id == "resize" and selected(keys, "Jump") and jump
    self.handle.Visible = false
    if resize then
        local x, y = jump.x + jump.w + 2, jump.y + jump.h - 26
        if x + touch <= canvas.x + canvas.w and y >= canvas.y and y + touch <= canvas.y + canvas.h then
            self.handle.Position, self.handle.Size = UDim2.fromOffset(x - canvas.x, y - canvas.y), UDim2.fromOffset(touch, touch)
            self.handle.Visible = true
        end
    end
    local rotate = self.rotationHandle.gui
    rotate.Visible = false
    if self.lesson.id == "rotate" and selected(keys, "Jump") and jump then
        local x, y = jump.x + jump.w + 6, jump.y - 16
        if x + touch <= canvas.x + canvas.w then
            y = math.max(canvas.y, math.min(y, canvas.y + canvas.h - touch))
            rotate.Position, rotate.Size = UDim2.fromOffset(x - canvas.x, y - canvas.y), UDim2.fromOffset(touch, touch)
            rotate.Visible = true
        end
    end
    self.practicePanel.Visible = self.lesson.id == "panel" and self.sampleRect ~= nil
    if self.practicePanel.Visible then
        local sample = self.sampleRect
        self.practicePanel.Position = UDim2.fromOffset(sample.x - canvas.x, sample.y - canvas.y)
        self.practicePanel.Size = UDim2.fromOffset(sample.w, sample.h)
    end
    local info = self:_sizeInfo()
    if info then self.thumb.Position = UDim2.fromScale(math.max(0, math.min(1, (info.scale - info.minimum) / (info.maximum - info.minimum))), .5) end
    self.angleThumb.Position = UDim2.fromScale(math.max(0, math.min(1, (self.angle + 180) / 360)), .5)
    self.opacityThumb.Position = UDim2.fromScale(self.opacity / 100, .5)
    self.angleLabel.Text = string.format("%d°", math.floor(self.angle + .5))
    self.opacityLabel.Text = string.format("%d%%", math.floor(self.opacity + .5))
end

local function relativeRect(child, before, after)
    local sx, sy = after.w / before.w, after.h / before.h
    return {x = after.x + (child.x - before.x) * sx, y = after.y + (child.y - before.y) * sy,
        w = child.w * sx, h = child.h * sy}
end

function Onboarding:_movePracticeTarget(key, rect)
    local original = self.before.rects[key]
    local placed = Layout.place(rect, self.canvasRect, rect.x, rect.y)
    self.rects[key] = placed
    if not self.targets[key].scope then return end
    for partKey, part in pairs(self.targets) do
        local parent = part.parentKey
        while parent do
            if parent == key then
                local child = self.before.rects[partKey]
                if child then self.rects[partKey] = relativeRect(child, original, placed) end
                break
            end
            parent = self.targets[parent].parentKey
        end
    end
end

function Onboarding:_createInput()
    local owner = self
    local app = {selection = {}, editing = true, preferences = {aspectLock = true, gridSize = 24}}
    app.discovery = {}
    function app:canvasHits(x, y)
        if owner.lesson.id == "scope" or owner.lesson.id == "compatibility" then return owner:_abilityHits(x, y) end
        local hits, primary = {}, nil
        for _, key in ipairs({"Jump", "Move"}) do
            if Coordinates.contains(owner.rects[key], x, y) then hits[#hits + 1] = owner.targets[key]; primary = primary or owner.targets[key] end
        end
        if owner.lesson.id == "layers" and Coordinates.contains(Coordinates.rect(owner.overlay), x, y) then
            table.insert(hits, 1, owner.overlayRecord)
        end
        return hits, primary or false
    end
    function app.discovery:hit(x, y) return app:canvasHits(x, y, false) end
    function app.discovery:get(key) return owner.targets[key] or (key == "Overlay" and owner.overlayRecord or nil) end
    function app.discovery:list() return {owner.targets.Jump, owner.targets.Move} end
    function app:capability(key)
        local managed = owner.lesson.id == "compatibility" and key ~= "AbilityBar"
        local record = self.discovery:get(key)
        return {supported = not managed and record and record.editable == true, reason = managed and managedHelp or nil}
    end
    function app:status(text) owner:_describe(text) end
    function app:getRects(_, operation)
        local rects, keys, skipped = {}, {}, 0
        for _, key in ipairs(self.selection) do
            local rect = owner.rects[key]
            if rect and (not operation or self:capability(key).supported) then
                rects[#rects + 1], keys[#keys + 1] = rect, key
            else
                skipped = skipped + 1
            end
        end
        return rects, keys, skipped
    end
    function app:currentBounds() return Geometry.bounds(self:getRects()) end
    function app:select(key, additive) owner:_select(key, additive) end
    function app:clearSelection() owner:_select(nil) end
    function app:selectMany(keys) self.selection = keys; owner:_drawTargets() end
    function app:sizeInfo(bounds) return owner:_sizeInfo(bounds) end
    function app:sizeRects(rects, w, h)
        local bounds = Geometry.bounds(rects)
        return Geometry.scale(rects, {x = bounds.x, y = bounds.y, w = w, h = h}, false)
    end
    function app:appearanceInfo(kind, scope)
        local jump = owner.rects.Jump
        if not jump or self.selection[1] ~= "Jump" then return nil end
        return {value = kind == "rotation" and owner.angle or owner.opacity, minimum = kind == "rotation" and -180 or 0,
            maximum = kind == "rotation" and 180 or 100, keys = {"Jump"}, skipped = 0, scope = scope,
            pivot = {x = jump.x + jump.w / 2, y = jump.y + jump.h / 2}}
    end
    function app:updateAppearance(kind, value)
        if kind == "rotation" then
            owner.angle = value >= -180 and value <= 180 and value or (value + 180) % 360 - 180
        else owner.opacity = math.max(0, math.min(100, value)) end
        owner:_drawTargets()
        return true
    end
    function app:beginGesture(label)
        local rects = {}
        for key, rect in pairs(owner.rects) do rects[key] = rect end
        owner.before = {rects = rects, angle = owner.angle, opacity = owner.opacity, label = label}
        return true
    end
    function app:updateGesture(rects, keys)
        for index, key in ipairs(keys) do owner:_movePracticeTarget(key, rects[index]) end
        owner:_drawTargets()
        return true
    end
    function app:cancelGesture()
        local before = owner.before
        if before then
            owner.rects, owner.angle, owner.opacity, owner.before = before.rects, before.angle, before.opacity, nil
            owner:_drawTargets()
        end
    end
    function app:endGesture()
        local state = owner.before
        owner.before = nil
        if not state then return end
        local before, after = state.rects.Jump, owner.rects.Jump
        if before and after then
            if (owner.lesson.id == "move" and (math.abs(before.x - after.x) > 5 or math.abs(before.y - after.y) > 5))
                or (owner.lesson.id == "resize" and math.abs(before.w - after.w) > 2)
                or (owner.lesson.id == "rotate" and math.abs(state.angle - owner.angle) > 2)
                or (owner.lesson.id == "opacity" and math.abs(state.opacity - owner.opacity) > 2) then owner:_completeLesson() end
        end
        if owner.lesson.id == "scope" and state.label == "Pinch resize" then
            local key = self.selection[1]
            if key and state.rects[key] and owner.targets[key].scope == "whole"
                and math.abs(state.rects[key].w - owner.rects[key].w) > 2 then
                owner.scopeResized = true
                owner:_scopeComplete()
            end
        elseif owner.lesson.id == "compatibility" and not same(state.rects.AbilityBar, owner.rects.AbilityBar) then
            owner:_completeLesson()
        end
    end

    local practiceUI = {canvas = self.canvas, slider = self.slider, handles = {{gui = self.handle, marker = self.marker, handle = "se"}},
        rotationHandle = self.rotationHandle, visualSliders = {rotation = self.angleSlider, opacity = self.opacitySlider},
        opacityScope = "element", inspectorGrip = self.practiceGrip}
    function practiceUI:pointInPanel(x, y) return not Coordinates.contains(owner.canvasRect, x, y) end
    function practiceUI:setBox() end
    function practiceUI:setGuides() end
    function practiceUI:sliderTrackRect() return owner.slider.Visible and Coordinates.rect(owner.track) or nil end
    function practiceUI:visualSliderTrackRect(kind)
        local track = kind == "rotation" and owner.angleTrack or owner.opacityTrack
        return track.Parent.Visible and Coordinates.rect(track) or nil
    end
    function practiceUI:getTransformTool()
        local mode = owner.lesson.id
        return mode == "resize" and "size" or (mode == "rotate" or mode == "opacity") and mode or "move"
    end
    function practiceUI:surfacePosition()
        local rect = owner.sampleRect
        if rect then return rect.x, rect.y end
    end
    function practiceUI:moveSurface(_, x, y)
        owner.sampleStart = owner.sampleStart or owner.sampleRect
        owner.sampleRect = Layout.place(owner.sampleRect, owner.canvasRect, x, y)
        owner:_drawTargets()
    end
    function practiceUI:finishSurfaceMove(_, cancelled)
        local before = owner.sampleStart
        if cancelled and before then owner.sampleRect = before; owner:_drawTargets()
        elseif before and not same(before, owner.sampleRect) then owner:_completeLesson() end
        owner.sampleStart = nil
    end
    local actual = self.services.UserInputService
    local practiceInput = {InputChanged = actual.InputChanged, InputEnded = actual.InputEnded, WindowFocusReleased = actual.WindowFocusReleased}
    function practiceInput:IsKeyDown(key) return actual:IsKeyDown(key) end
    function practiceInput:GetFocusedTextBox() return actual:GetFocusedTextBox() end
    self.app, self.practiceUI = app, practiceUI
    self.input = Input.new(app, practiceUI, {UserInputService = practiceInput})
end

function Onboarding:_highlightTargets(area)
    local found = {}
    if self.callbacks.highlight then
        for _, id in ipairs(self.lesson.highlights or {}) do
            local target = self.callbacks.highlight(id)
            local rect = type(target) == "table" and target.x and target or Coordinates.rect(target)
            if rect and Coordinates.intersection(rect, area) then found[#found + 1] = rect end
        end
    end
    self.highlightRects = found
    for index, rect in ipairs(found) do
        local object = self.highlightFrames[index]
        if not object then
            object = make("Frame", {Name = "EditorHighlight", BackgroundTransparency = 1, Active = false, ZIndex = layer + 1}, self.shield)
            pcall(function() object.Interactable = false end)
            Design.stroke(object, C.cyan, 2, .14)
            Design.round(object, 8)
            self.highlightFrames[index] = object
        end
        place(object, rect)
        object.Visible = true
    end
    for index = #found + 1, #self.highlightFrames do self.highlightFrames[index].Visible = false end
end

function Onboarding:_layout()
    local area, id = self.area, self.lesson.id
    if not area or area.w < 160 or area.h < 54 then self.shield.Visible = false; self.coachRect, self.padRect = nil, nil; return end
    self.shield.Visible = true
    self:_highlightTargets(area)
    local landscape = area.w >= 466 and area.w >= area.h * 1.12
    local abilities = id == "scope" or id == "compatibility"
    local practice = self.lesson.done ~= nil and area.h >= (landscape and 190 or 278) and (not abilities or area.w >= 226)
    if self.lesson.done and practice ~= self.practiceAvailable and not self.lessonComplete then
        self:_describe(practice and self.lesson.body or "Make more room to try this exercise, or tap Next to continue.")
    end
    self.practiceAvailable = practice
    landscape = landscape and practice
    local totalWidth = math.min(area.w, landscape and 720 or 420)
    local coachWidth = landscape and math.min(310, math.floor(totalWidth * .43)) or totalWidth
    local offerTour = self.mode == "quick" and self.step == #quick and area.h >= 174
    local coachHeight = math.min(area.h, practice and 186 or (offerTour and 242 or 216))
    local padHeight, padWidth = 0, 0
    if practice then
        padWidth = landscape and totalWidth - coachWidth - 10 or totalWidth
        padHeight = landscape and math.min(242, area.h) or math.min(245, math.floor(area.h * .56))
        if not landscape then coachHeight = math.min(coachHeight, area.h - padHeight - 10) end
    end
    local fullHeight = landscape and math.max(coachHeight, padHeight) or coachHeight + (practice and padHeight + 10 or 0)
    local x, y = area.x + math.floor((area.w - totalWidth) / 2), area.y + math.floor((area.h - fullHeight) / 2)
    self.coachRect = {x = x, y = y, w = coachWidth, h = coachHeight}
    if not practice then
        for _, candidateY in ipairs({y, area.y + area.h - coachHeight, area.y}) do
            local candidate = {x = x, y = candidateY, w = coachWidth, h = coachHeight}
            local clear = true
            for _, target in ipairs(self.highlightRects) do if Layout.intersects(candidate, target) then clear = false; break end end
            if clear then self.coachRect = candidate; break end
        end
    end
    place(self.coach, self.coachRect)
    local width = math.min(88, math.floor((coachWidth - 20 - 8) / 3))
    self.skip.Position, self.skip.Size = UDim2.new(0, 10, 1, -53), UDim2.fromOffset(width, touch)
    self.back.Position, self.back.Size = UDim2.new(.5, -width / 2, 1, -53), UDim2.fromOffset(width, touch)
    self.next.Position, self.next.Size = UDim2.new(1, -10 - width, 1, -53), UDim2.fromOffset(width, touch)
    self.tour.Visible, self.back.Visible = offerTour, self.step > 1
    self.instructions.Size = UDim2.new(1, -28, 1, offerTour and -166 or -120)
    self.descriptionWidth = math.max(1, coachWidth - 34)
    self:_describe(self.description.Text)
    self.progress.Visible, self.heading.Visible, self.instructions.Visible = coachHeight >= 108, coachHeight >= 108, coachHeight >= 140
    self.pad.Visible = practice
    self.padRect, self.canvasRect = nil, nil
    if not practice then self.rects = {}; return end
    self.padRect = {x = landscape and x + coachWidth + 10 or x, y = landscape and y or y + coachHeight + 10, w = padWidth, h = padHeight}
    place(self.pad, self.padRect)
    local controls = abilities or id == "resize" or id == "layers" or id == "group" or id == "rotate" or id == "opacity" or id == "reset"
    self.controls.Visible = controls
    local height = padHeight - (controls and 85 or 42)
    self.canvasRect = {x = self.padRect.x + 10, y = self.padRect.y + 31, w = padWidth - 20, h = height}
    self.canvas.Position, self.canvas.Size = UDim2.fromOffset(10, 31), UDim2.fromOffset(padWidth - 20, height)
    self:_drawTools()
end

function Onboarding:_relocateAbilities(oldCanvas)
    local canvas = self.canvasRect
    local previous = oldCanvas and self.rects.AbilityBar
    if previous then
        local x = canvas.x + (previous.x - oldCanvas.x) / oldCanvas.w * canvas.w
        local y = canvas.y + (previous.y - oldCanvas.y) / oldCanvas.h * canvas.h
        local bar = Layout.place(previous, canvas, x, y)
        local placed = {AbilityBar = bar}
        for key, rect in pairs(self.rects) do
            if key ~= "AbilityBar" then placed[key] = relativeRect(rect, previous, bar) end
        end
        self.rects = placed
        return
    end
    local w = math.min(242, canvas.w - 26)
    local h = math.min(90, math.floor(canvas.h * .65))
    local bar = {x = canvas.x + (canvas.w - w) / 2, y = canvas.y + (canvas.h - h) / 2, w = w, h = h}
    local result = {AbilityBar = bar}
    local width = (bar.w - 32) / 3
    for index in ipairs(abilityNames) do
        local key = "Ability" .. index
        local card = {x = bar.x + 8 + (index - 1) * (width + 8), y = bar.y + 8, w = width, h = bar.h - 16}
        local badgeH = math.min(16, card.h * .30)
        local iconSize = math.min(23, card.h * .40)
        result[key] = card
        result[key .. "Badge"] = {x = card.x + 4, y = card.y + 4, w = 19, h = badgeH}
        result[key .. "Icon"] = {x = card.x + (card.w - iconSize) * .55, y = card.y + card.h * .25, w = iconSize, h = iconSize}
        result[key .. "Label"] = {x = card.x + 5, y = card.y + card.h - 17, w = card.w - 10, h = 14}
        result[key .. "Overlay"] = {x = card.x + card.w - 7, y = card.y + 6, w = 3, h = card.h * .59}
    end
    self.rects = result
end

function Onboarding:_relocate(oldCanvas)
    local canvas = self.canvasRect
    if not canvas then self.rects = {}; return end
    if self.lesson.id == "scope" or self.lesson.id == "compatibility" then
        self:_relocateAbilities(oldCanvas)
        self:_drawTargets()
        return
    end
    local targetSize = math.min(64, math.max(16, math.floor(canvas.h * .56)))
    local nextRects = {}
    for _, key in ipairs(self.lesson.id == "group" and {"Jump", "Move"} or {"Jump"}) do
        local previous = oldCanvas and self.rects[key]
        local fraction = key == "Move" and .73 or (self.lesson.id == "group" and .27 or .47)
        local x = canvas.x + canvas.w * fraction - targetSize / 2
        local y = canvas.y + canvas.h * .43 - targetSize / 2
        if previous then
            x = canvas.x + (previous.x - oldCanvas.x) / oldCanvas.w * canvas.w
            y = canvas.y + (previous.y - oldCanvas.y) / oldCanvas.h * canvas.h
        end
        nextRects[key] = Layout.place(previous or {w = targetSize, h = targetSize}, canvas, x, y)
    end
    self.rects = nextRects
    if self.lesson.id == "panel" then
        local sample = oldCanvas and self.sampleRect
        local jump = nextRects.Jump
        local x, y = jump.x - 24, jump.y - 30
        if sample then x, y = canvas.x + (sample.x - oldCanvas.x), canvas.y + (sample.y - oldCanvas.y) end
        self.sampleRect = Layout.place(sample or {w = 118, h = touch}, canvas, x, y)
    end
    self:_drawTargets()
end

function Onboarding:layout(area)
    local oldArea, oldCanvas = self.area, self.canvasRect
    self.area = area
    if not self.active then return end
    if not area or area.w < 160 or area.h < 54 then self:close(); return end
    if not same(oldArea, area) and self.input then self.input:cancel() end
    self:_layout()
    self:_relocate(oldCanvas)
end

function Onboarding:_go(step)
    self.input:cancel()
    local chapter = self.mode == "tour" and self.route[step][1] or nil
    self.step, self.lesson, self.lessonComplete, self.layerPicker = step, chapter and self.route[step][2] or self.route[step], false, false
    self.progressByMode[self.mode] = step
    local lesson = self.lesson
    local action = Reference.get(lesson.action)
    if (lesson.id == "scope" or lesson.id == "compatibility") and not self.targets.AbilityBar then self:_mountAbilities() end
    if self.lessonIcon then self.lessonIcon:Destroy() end
    self.lessonIcon = action.icon and Lucide.mount(self.coach, action.icon,
        {size = 18, color = C.cyan, position = UDim2.fromOffset(14, 35), anchor = Vector2.new(0, 0), zIndex = layer + 3}) or nil
    local headingLeft = self.lessonIcon and 40 or 14
    self.heading.Position, self.heading.Size = UDim2.fromOffset(headingLeft, 32), UDim2.new(1, -headingLeft - 14, 0, 28)
    self.progress.Text = chapter and string.format("%d / 7  •  %s", chapter, chapterNames[chapter])
        or string.format("QUICK START  %d / %d", step, #self.route)
    self.heading.Text = lesson.title or action.label
    self:_describe(lesson.body or action.how)
    self.instructions.CanvasPosition = Vector2.new(0, 0)
    self.description.TextColor3 = C.subtleText
    self.next.Text = self.mode == "quick" and step == 1 and "Start" or (step == #self.route and "Finish" or "Next")
    self.app.preferences.multiSelect, self.multi.Text = false, "Multi"
    self.app.openSelectThrough = lesson.id == "layers" and function(_, hits) return self:_showLayers(hits) end or nil
    self.angle, self.opacity = lesson.id == "reset" and 28 or 0, lesson.id == "reset" and 55 or 100
    self.scopeMode, self.scopeSeen, self.scopeResized = "whole", {}, false
    self.practiceUI.opacityScope, self.scopeButton.Text = "element", "Element only"
    self.sampleRect, self.sampleStart, self.practiceAvailable = nil, nil, nil
    local hasSelection = lesson.id == "move" or lesson.id == "resize" or lesson.id == "rotate" or lesson.id == "opacity" or lesson.id == "reset"
    self.app.selection = hasSelection and {"Jump"} or {}
    self:_layout()
    self:_relocate()
    self:_notify()
end

function Onboarding:start(mode, resume)
    if self.dead or self.active then return false end
    self.mode = mode == "tour" and "tour" or "quick"
    self.route = self.mode == "tour" and tour or quick
    local step = resume and self:_resumeStep(self.mode) or 1
    self.active, self.rects = true, {}
    self.descriptionWidth, self.measuredDescriptionWidth, self.measuredDescription = nil, nil, nil
    self:_mount()
    self:_createInput()
    self:_go(step or 1)
    return true
end

function Onboarding:_advance()
    if self.step == #self.route then self:_finish("completed") else self:_go(self.step + 1) end
end

function Onboarding:_finish(outcome)
    local mode = self.mode
    self:close(outcome)
    if self.callbacks.finished then self.callbacks.finished(outcome, mode) end
end

function Onboarding:close(outcome)
    if not self.active then return end
    local mode = self.mode
    local progress = outcome ~= "completed" and self.step > 1 and self.step or nil
    self.progressByMode[mode] = progress or false
    self.active = false
    self.input:destroy()
    for _, connection in ipairs(self.connections) do connection:Disconnect() end
    self.connections = {}
    self.shield:Destroy()
    self.input, self.app, self.practiceUI, self.shield, self.coachRect, self.padRect, self.canvasRect = nil, nil, nil, nil, nil, nil, nil
    self.before, self.rects, self.highlightRects, self.highlightFrames = nil, nil, nil, nil
    self.lessonIcon, self.targets, self.selectionScopeButtons, self.selectBar, self.padTitle = nil, nil, nil, nil, nil
    self:_notify()
    if self.callbacks.saveProgress then self.callbacks.saveProgress(mode, progress) end
end

function Onboarding:destroy()
    if self.dead then return end
    self:close()
    self.dead = true
    self.callbacks, self.area = {}, nil
end

return Onboarding
end

-- Module: Profiles
__factories["Profiles"] = function(require)
local Config = require("Config")
local Util = require("Util")
local Profiles = {}
Profiles.__index = Profiles
local priorities = {global = 1, experience = 2, place = 3, device = 4, orientation = 5}

local function find(data, id)
    for index, profile in ipairs(data.profiles) do
        if profile.id == id then return profile, index end
    end
end

local function cleanName(name)
    if type(name) ~= "string" then return nil end
    name = name:match("^%s*(.-)%s*$")
    if #name == 0 or #name > 64 or name:find("[%c]") then return nil end
    return name
end

function Profiles.new(data, storage, context, log)
    data = data or Config.empty()
    local valid, reason = Config.validate(data)
    assert(valid, "Invalid initial configuration: " .. tostring(reason))
    data = Util.copy(data)
    local checkpoint = Util.copy(data)
    return setmetatable({data = data, checkpoint = checkpoint, diskCheckpoint = checkpoint, storage = storage, context = context,
        log = log or function() end, serial = 0, suspended = false, editTargets = {}}, Profiles)
end

function Profiles:list(allScopes)
    local profiles = {}
    for _, profile in ipairs(self.data.profiles) do
        if allScopes or Config.applies(profile, self.context) then profiles[#profiles + 1] = profile end
    end
    table.sort(profiles, function(a, b)
        local first, second = a.name:lower(), b.name:lower()
        if first == second then return a.id < b.id end
        return first < second
    end)
    return profiles
end

local function contextKey(context)
    return table.concat({tostring(context.experience), tostring(context.place), tostring(context.device), tostring(context.orientation)}, ":")
end

local function activeById(data, context, id)
    local profile = id and find(data, id)
    if profile and Config.applies(profile, context) and data.active[Config.scopeKey(profile)] == id then return profile end
end

function Profiles:editTargetId(context)
    context = context or self.context
    local id = self.editTargets[contextKey(context)]
    return activeById(self.data, context, id) and id or nil
end

function Profiles:setEditTarget(id, context)
    context = context or self.context
    if id ~= nil and not activeById(self.data, context, id) then return false end
    self.editTargets[contextKey(context)] = id
    return true
end

function Profiles:active(context)
    context = context or self.context
    local selected = self:editTargetId(context)
    if selected then return find(self.data, selected) end
    local active = Config.activeProfiles(self.data, context)
    return active[#active]
end

function Profiles:resetTarget(context)
    context = context or self.context
    local active = Config.activeProfiles(self.data, context)
    local profile = active[#active]
    if profile and profile.scope == "orientation" and profile.device == context.device then return profile end
end

function Profiles:_id()
    repeat
        self.serial = self.serial + 1
        local id = "profile-" .. tostring(os.time()) .. "-" .. tostring(self.serial)
        if not find(self.data, id) then return id end
    until false
end

function Profiles:create(name, scope)
    if self.saving then return nil, "Wait for the current Save to finish." end
    if self.preview then return nil, "Apply or cancel the preview before managing profiles." end
    name = cleanName(name)
    if not name then return nil, "Choose a profile name of 1–64 readable characters." end
    scope = scope or "place"
    if not priorities[scope] then return nil, "Unknown profile scope." end
    local profile = {id = self:_id(), name = name, scope = scope, layout = {}, groups = {}, preferences = {}}
    if scope == "experience" then profile.scopeId = self.context.experience end
    if scope == "place" or scope == "device" or scope == "orientation" then profile.scopeId = self.context.place end
    if scope == "device" or scope == "orientation" then profile.device = self.context.device end
    if scope == "orientation" then profile.orientation = self.context.orientation end
    local valid, err = Config.validateProfile(profile)
    if not valid then return nil, err end
    local candidate = Util.copy(self.data)
    candidate.profiles[#candidate.profiles + 1] = profile
    local accepted, reason = Config.validate(candidate)
    if not accepted then return nil, reason end
    self.data = candidate
    self.log("Created profile " .. name .. "; preview and Apply to activate, Save to persist.")
    return find(self.data, profile.id)
end

function Profiles:rename(id, name)
    if self.saving then return false, "Wait for the current Save to finish." end
    if self.preview then return false, "Apply or cancel the preview before managing profiles." end
    name = cleanName(name)
    if not name then return false, "Choose a profile name of 1–64 readable characters." end
    local profile = find(self.data, id)
    if not profile then return false, "Profile not found." end
    profile.name = name
    return true, "Profile renamed in memory; Save to persist."
end

function Profiles:duplicate(id, name)
    if self.saving then return nil, "Wait for the current Save to finish." end
    if self.preview then return nil, "Apply or cancel the preview before managing profiles." end
    local source = find(self.data, id)
    if not source then return nil, "Profile not found." end
    name = cleanName(name or (source.name:sub(1, 58) .. " copy"))
    if not name then return nil, "Choose a profile name of 1–64 readable characters." end
    local profile = Util.copy(source)
    profile.id, profile.name = self:_id(), name
    local candidate = Util.copy(self.data)
    candidate.profiles[#candidate.profiles + 1] = profile
    local ok, reason = Config.validate(candidate)
    if not ok then return nil, reason end
    self.data = candidate
    return find(self.data, profile.id)
end

function Profiles:delete(id, confirmed)
    if self.saving then return false, "Wait for the current Save to finish." end
    if confirmed ~= true then return false, "Confirm profile deletion. GUI elements and original layouts will be preserved." end
    if self.preview then return false, "Apply or cancel the profile preview first." end
    local profile, index = find(self.data, id)
    if not profile then return false, "Profile not found." end
    table.remove(self.data.profiles, index)
    for key, activeId in pairs(self.data.active) do
        if activeId == id then self.data.active[key] = nil end
    end
    self.revisions = nil
    return true, "Profile deleted in memory; Save to persist. GUI elements were preserved."
end

function Profiles:isActive(id, context)
    return activeById(self.data, context or self.context, id) ~= nil
end

function Profiles:resolve(context)
    if self.suspended then return {}, Util.copy(self.data.preferences or {}), {} end
    return Config.resolve(self.data, context or self.context)
end

function Profiles:beginPreview(id, context)
    if self.saving then return nil, "Wait for the current Save to finish." end
    context = context or self.context
    local profile = find(self.data, id)
    if not profile then return nil, "Profile not found." end
    if not Config.applies(profile, context) then return nil, "This profile belongs to another experience, place, device or orientation." end
    local candidate = Util.copy(self.data)
    candidate.active[Config.scopeKey(profile)] = profile.id
    local valid, err = Config.validate(candidate)
    if not valid then return nil, err end
    local layout, preferences, groups = Config.resolve(candidate, context)
    local active = Config.activeProfiles(candidate, context)
    self.preview = {kind = "profile", id = profile.id, data = candidate, context = Util.copy(context),
        preferences = preferences, groups = groups, overlaid = active[#active].id ~= profile.id}
    return layout, nil, preferences, groups
end

function Profiles:applyPreview()
    if self.saving then return false, "Wait for the current Save to finish." end
    if not self.preview then return false, "No profile preview to apply." end
    local valid, err = Config.validate(self.preview.data)
    if not valid then return false, err end
    local preview = self.preview
    self.data = preview.data
    self:setEditTarget(preview.id, preview.context)
    self.preview = nil
    self.suspended = false
    return true, "Profile preview applied in memory; Save to persist."
end

function Profiles:cancelPreview()
    self.preview = nil
    return true, "Preview canceled; active profile unchanged."
end

local function differences(before, after)
    local changes = {}
    for key, value in pairs(after) do
        if not Util.equal(value, before[key]) then changes[#changes + 1] = {key = key, before = before[key], value = value} end
    end
    for key, value in pairs(before) do
        if after[key] == nil then changes[#changes + 1] = {key = key, before = value} end
    end
    return changes
end

local function patchLayout(layout, changes, inherited)
    for _, change in ipairs(changes) do
        local key, before, value = change.key, change.before, change.value
        local own, base = layout[key], inherited[key]
        if not value then
            layout[key] = base and {descriptor = Util.copy(before.descriptor), removed = true} or nil
        elseif own and not own.inherit and not own.removed then
            -- Preserve untouched fields of legacy full overrides, even when a higher layer is visible.
            for _, property in ipairs(Config.LAYOUT_PROPERTIES) do
                if not before or not Util.equal(before[property], value[property]) then own[property] = Util.copy(value[property]) end
            end
        elseif not base then
            layout[key] = Util.copy(value)
        else
            local patch = own and own.inherit and own or {descriptor = Util.copy(value.descriptor), inherit = true}
            local clear = patch.clear or {}
            local hasOverride = false
            for _, property in ipairs(Config.LAYOUT_PROPERTIES) do
                if not before or not Util.equal(before[property], value[property]) then
                    local inherit = Util.equal(base[property], value[property])
                    if inherit then
                        patch[property], clear[property] = nil, nil
                    else
                        patch[property] = Util.copy(value[property])
                        clear[property] = value[property] == nil or nil
                    end
                end
                if patch[property] ~= nil or clear[property] then hasOverride = true end
            end
            patch.clear = next(clear) and clear or nil
            layout[key] = hasOverride and patch or nil
        end
    end
end

local function patchValues(map, changes, inherited, canRemove)
    for _, change in ipairs(changes) do
        local key, value = change.key, change.value
        if Util.equal(value, inherited[key]) then map[key] = nil
        elseif value == nil and canRemove then map[key] = false
        else map[key] = Util.copy(value) end
    end
end

local function conflicts(changes, resolved, layout)
    for _, change in ipairs(changes) do
        local before, value, actual = change.before, change.value, resolved[change.key]
        if layout and before and value and actual then
            for _, property in ipairs(Config.LAYOUT_PROPERTIES) do
                if not Util.equal(before[property], value[property]) and not Util.equal(value[property], actual[property]) then return true end
            end
        elseif not Util.equal(value, actual) then return true end
    end
    return false
end

function Profiles:save(layout, groups, preferences, baseline, context, options)
    if self.preview then return false, "Apply or cancel the preview before saving." end
    if self.saving then return false, "Save is already in progress." end
    context = context or self.context
    local reset = type(options) == "table" and options.resetAll == true
    if reset and ((context.device ~= "touch" and context.device ~= "desktop")
        or (context.orientation ~= "landscape" and context.orientation ~= "portrait")) then
        return false, "Reset requires a recognized device and screen orientation."
    end
    layout, groups, preferences = layout or {}, groups or {}, preferences or {}
    local stateValid, stateReason = Config.validateState({layout = layout, groups = groups, preferences = preferences})
    if not stateValid then return false, "Checkpoint rejected. " .. tostring(stateReason) end
    if not baseline then
        local previousLayout, previousPrefs, previousGroups = self:resolve(context)
        baseline = {layout = previousLayout, preferences = previousPrefs, groups = previousGroups}
    end
    local layoutChanges = differences(baseline.layout, layout)
    local groupChanges = differences(baseline.groups, groups)
    local prefChanges = differences(baseline.preferences, preferences)
    local candidate = Util.copy(self.data)
    local resetProfileId
    if reset or #layoutChanges + #groupChanges + #prefChanges > 0 then
        local active = self:active(context)
        if reset then active = self:resetTarget(context) end
        local profile = active and find(candidate, active.id)
        if not profile then
            profile = {id = self:_id(), name = "Default place", scope = "place", scopeId = context.place, layout = {}, groups = {}, preferences = {}}
            if reset then
                profile.name, profile.scope = "Original " .. context.orientation .. " layout", "orientation"
                profile.device, profile.orientation = context.device, context.orientation
            end
            candidate.profiles[#candidate.profiles + 1] = profile
            candidate.active[Config.scopeKey(profile)] = profile.id
        end
        local inheritedLayout, inheritedPrefs, inheritedGroups = Config.resolve(candidate, context, profile.id)
        profile.groups, profile.preferences = profile.groups or {}, profile.preferences or {}
        if reset then
            profile.resetLayout, profile.layout = true, Util.copy(layout)
            resetProfileId = profile.id
        else
            patchLayout(profile.layout, layoutChanges, profile.resetLayout and {} or inheritedLayout)
        end
        patchValues(profile.groups, groupChanges, inheritedGroups, true)
        patchValues(profile.preferences, prefChanges, inheritedPrefs, false)
        local valid, reason = Config.validate(candidate)
        if not valid then return false, "Save rejected. " .. tostring(reason) .. ". Use an experience or place profile for game-specific elements." end
        local candidateLayout, candidatePrefs, candidateGroups = Config.resolve(candidate, context)
        if (reset and not Util.equal(layout, candidateLayout)) or (not reset and conflicts(layoutChanges, candidateLayout, true))
            or conflicts(groupChanges, candidateGroups) or conflicts(prefChanges, candidatePrefs) then
            return false, "A more specific profile overrides these edits. Choose that profile to save them here."
        end
    end
    self.saving = true
    local ran, saved, message, memoryOnly = pcall(self.storage.save, self.storage, candidate, self.diskCheckpoint)
    self.saving = nil
    if not ran then return false, "Save could not complete. Your edits are still open." end
    if saved or memoryOnly then
        self.data = candidate
        self.checkpoint = Util.copy(candidate)
        if saved then self.diskCheckpoint = self.checkpoint end
        if resetProfileId then self:setEditTarget(resetProfileId, context) end
    end
    self.log(message)
    return saved, message, saved == true or memoryOnly == true
end

function Profiles:import(text)
    return self.storage:import(text)
end

function Profiles:beginImport(text, overwriteConfirmed, context)
    if self.saving then return nil, "Wait for the current Save to finish." end
    context = context or self.context
    local incoming, err = self:import(text)
    if not incoming then return nil, err end
    local candidate = Util.copy(self.data)
    local conflicts = false
    for _, profile in ipairs(incoming.profiles) do
        local existing = find(candidate, profile.id)
        if existing and not Util.equal(existing, profile) then conflicts = true end
    end
    local currentPreferences, incomingPreferences = candidate.preferences or {}, incoming.preferences or {}
    for key, value in pairs(incomingPreferences) do
        if currentPreferences[key] ~= nil and not Util.equal(currentPreferences[key], value) then conflicts = true end
    end
    for key, id in pairs(incoming.active) do
        if candidate.active[key] ~= nil and candidate.active[key] ~= id then conflicts = true end
    end
    for name, members in pairs(incoming.groups or {}) do
        if candidate.groups and candidate.groups[name] and not Util.equal(candidate.groups[name], members) then conflicts = true end
    end
    if conflicts and overwriteConfirmed ~= true then return nil, "Import would overwrite existing profiles, activation, groups, or preferences. Confirm overwrite, then preview again." end
    for _, profile in ipairs(incoming.profiles) do
        local existing, index = find(candidate, profile.id)
        if existing then
            local oldSlot = Config.scopeKey(existing)
            if oldSlot ~= Config.scopeKey(profile) and candidate.active[oldSlot] == profile.id then candidate.active[oldSlot] = nil end
            candidate.profiles[index] = Util.copy(profile)
        else
            candidate.profiles[#candidate.profiles + 1] = Util.copy(profile)
        end
    end
    for key, id in pairs(incoming.active) do candidate.active[key] = id end
    if next(incomingPreferences) then
        for key, value in pairs(incomingPreferences) do currentPreferences[key] = Util.copy(value) end
        candidate.preferences = currentPreferences
    end
    if incoming.groups then
        candidate.groups = candidate.groups or {}
        for name, members in pairs(incoming.groups) do candidate.groups[name] = Util.copy(members) end
    end
    local valid, reason = Config.validate(candidate)
    if not valid then return nil, "Merged import rejected: " .. tostring(reason) end
    local layout, preferences, groups = Config.resolve(candidate, context)
    self.preview = {kind = "import", data = candidate, context = Util.copy(context), preferences = preferences, groups = groups}
    return layout, nil, preferences, groups
end

function Profiles:export()
    return self.storage:export(self.checkpoint)
end

-- Stable across JSON key ordering. Used to detect a changed draft checkpoint.
local function revision(data, context)
    local hash, second = 5381, 2166136261
    local function update(value)
        for index = 1, #value do
            local byte = value:byte(index)
            hash = (hash * 33 + byte) % 4294967296
            second = (second * 65599 + byte) % 4294967296
        end
    end
    local function visit(value)
        local kind = type(value)
        if kind ~= "table" then
            local stringValue = kind == "number" and string.format("%.17g", value) or tostring(value)
            update(kind .. #stringValue .. ":" .. stringValue)
            return
        end
        local keys = {}
        for key in pairs(value) do keys[#keys + 1] = key end
        table.sort(keys)
        update("{")
        for _, key in ipairs(keys) do visit(key); visit(value[key]) end
        update("}")
    end
    visit(data.preferences or {})
    visit(data.groups or {})
    for _, profile in ipairs(Config.activeProfiles(data, context)) do
        visit(profile.id)
        visit(Config.scopeKey(profile))
        if profile.resetLayout then visit("original layout override") end
        visit(profile.layout)
        visit(profile.groups or {})
        visit(profile.preferences or {})
    end
    return string.format("%.0f:%.0f", hash, second)
end

function Profiles:_draftRevision(context)
    if self.revisionData ~= self.data or not self.revisions then
        self.revisionData, self.revisions = self.data, {}
    end
    local key = contextKey(context)
    if not self.revisions[key] then self.revisions[key] = revision(self.data, context) end
    return self.revisions[key]
end

function Profiles:draftReference(context)
    context = context or self.context
    local active = self:active(context)
    return {profileId = active and active.id or false, revision = self:_draftRevision(context)}
end

function Profiles:matchesDraftReference(reference, context)
    if reference == nil then return true end
    context = context or self.context
    if reference.profileId == false then
        if self:active(context) then return false end
    elseif not activeById(self.data, context, reference.profileId) then
        return false
    end
    return reference.revision == self:_draftRevision(context)
end

function Profiles:suspend(value)
    self.suspended = value == true
    return self.suspended
end

return Profiles
end

-- Module: SmartLayers
__factories["SmartLayers"] = function(require)
local SmartLayers = {}

local builtins = {
    JumpButton = {"Jump button", "JMP"},
    ThumbstickFrame = {"Classic joystick", "JOY"},
    DynamicThumbstickFrame = {"Dynamic joystick zone", "JOY"},
}
local icons = {
    Frame = "FR", CanvasGroup = "GR", ScrollingFrame = "SC",
    TextButton = "BTN", ImageButton = "BTN", TextBox = "IN",
    TextLabel = "TXT", ImageLabel = "IMG", ViewportFrame = "3D", VideoFrame = "VID",
}
local textClasses = {TextButton = true, TextLabel = true, TextBox = true}
local imageClasses = {ImageButton = true, ImageLabel = true}

local function nonempty(value)
    return type(value) == "string" and value:find("%S") ~= nil
end

local function paintedAlpha(value)
    return type(value) == "number" and value < 0.99
end

function SmartLayers.hasImage(object)
    local class = object.ClassName
    if class == "ViewportFrame" then return object.CurrentCamera ~= nil end
    if not imageClasses[class] then return false end
    if nonempty(object.Image) then return true end
    local ok, hasContent = pcall(function()
        local content = object.ImageContent
        return content ~= nil and (content.Object ~= nil or nonempty(content.Uri))
    end)
    return ok and hasContent
end

function SmartLayers.hasText(object)
    local class = object.ClassName
    return textClasses[class] == true and object.MaxVisibleGraphemes ~= 0
        and (nonempty(object.Text) or class == "TextBox" and nonempty(object.PlaceholderText))
end

function SmartLayers.name(record)
    local builtin = builtins[record.builtin]
    local object = record.object
    if builtin then return builtin[1], builtin[2] end
    local name = object.Name:gsub("[_%-]+", " "):gsub("(%l)(%u)", "%1 %2"):gsub("(%u)(%u%l)", "%1 %2")
    name = name:match("^%s*(.-)%s*$")
    if not nonempty(name) then name = object.ClassName end
    return name, icons[object.ClassName] or "UI"
end

function SmartLayers.painted(object, strokes)
    if paintedAlpha(object.BackgroundTransparency) then return true end
    local class = object.ClassName
    local text
    if textClasses[class] then
        text = SmartLayers.hasText(object)
        if text and (paintedAlpha(object.TextTransparency) or paintedAlpha(object.TextStrokeTransparency)) then return true end
    elseif (imageClasses[class] or class == "ViewportFrame") and paintedAlpha(object.ImageTransparency) and SmartLayers.hasImage(object) then return true
    elseif class == "VideoFrame" and nonempty(object.Video) then return true end
    local borderWidth = 0
    for _, stroke in ipairs(strokes or {}) do
        local border = tostring(stroke.ApplyStrokeMode):match("Border$") ~= nil
        if stroke.Enabled ~= false and type(stroke.Thickness) == "number" and stroke.Thickness > 0
            and paintedAlpha(stroke.Transparency) then
            if border or not textClasses[class] then borderWidth = math.max(borderWidth, stroke.Thickness)
            elseif text then return true end
        end
    end
    if borderWidth > 0 then return true, borderWidth end
    return false, nil
end

function SmartLayers.actionable(record)
    local object = record.object
    return (record.interactive or object.ClassName == "Frame" and object.Active == true)
        and object.Interactable ~= false and object.Active ~= false
end

function SmartLayers.decorative(record)
    local class = record.object.ClassName
    return class == "ImageLabel" or class == "TextLabel"
end

return SmartLayers
end

-- Module: Storage
__factories["Storage"] = function(require)
-- Versioned JSON only: imported content is never executed.
local Config = require("Config")
local Util = require("Util")
local Storage = {}
Storage.__index = Storage
Storage.FILES = {
    saved = "HeavenlyAxis-v3.json",
    backup = "HeavenlyAxis-v3.backup.json",
    pending = "HeavenlyAxis-v3.pending.json",
    draft = "HeavenlyAxis-v3.draft.json",
}
Storage.EDITOR_FILES = {
    saved = "HeavenlyAxis-v3.editor.json",
    backup = "HeavenlyAxis-v3.editor.backup.json",
    pending = "HeavenlyAxis-v3.editor.pending.json",
}
Storage.MAX_BYTES = 2 * 1024 * 1024

local function validateState(state)
    if type(state) ~= "table" then return false, "Draft must contain a state" end
    for key in pairs(state) do
        if key ~= "layout" and key ~= "groups" and key ~= "preferences" and key ~= "context" and key ~= "reference" and key ~= "resetAll" then
            return false, "Unknown draft field"
        end
    end
    if state.context ~= nil then
        if type(state.context) ~= "table" then return false, "Invalid draft context" end
        for key, value in pairs(state.context) do
            if key ~= "experience" and key ~= "place" and key ~= "device" and key ~= "orientation" then return false, "Unknown draft context field" end
            if type(value) ~= "string" or #value > 80 then return false, "Invalid draft context value" end
        end
    end
    local reference = state.reference
    if reference ~= nil then
        if type(reference) ~= "table" then return false, "Invalid draft checkpoint reference" end
        for key in pairs(reference) do
            if key ~= "profileId" and key ~= "revision" then return false, "Unknown draft checkpoint field" end
        end
        local profileId, revision = reference.profileId, reference.revision
        if profileId ~= false and (type(profileId) ~= "string" or #profileId == 0 or #profileId > 128 or profileId:find("%c")) then
            return false, "Invalid draft profile ID"
        end
        if type(revision) ~= "string" or #revision > 21 or not revision:match("^%d+:%d+$") then
            return false, "Invalid draft revision"
        end
    end
    return Config.validateState({layout = state.layout or {}, groups = state.groups or {}, preferences = state.preferences or {}, resetAll = state.resetAll})
end

function Storage.new(capabilities, httpService, log, context)
    return setmetatable({capabilities = capabilities, http = httpService, log = log or function() end,
        blocked = false, context = context, draftOperations = {}, partialWrites = {}}, Storage)
end

function Storage:_draftPath(context)
    context = context or self.context
    if type(context) == "table" and type(context.experience) == "string" and type(context.place) == "string"
        and #context.experience <= 32 and #context.place <= 32
        and context.experience:match("^%d+$") and context.place:match("^%d+$")
        and (context.device == "touch" or context.device == "desktop")
        and (context.orientation == "portrait" or context.orientation == "landscape") then
        return "HeavenlyAxis-v3.draft." .. context.experience .. "." .. context.place .. "." .. context.device .. "." .. context.orientation .. ".json"
    end
    return self.FILES.draft
end

function Storage:_foreignDraft(value, context)
    local state = value and value.state
    local stored = type(state) == "table" and state.context
    return context and type(stored) == "table" and self:_draftPath(stored) ~= self.FILES.draft
        and not Util.equal(stored, context)
end

function Storage:_available()
    local f = self.capabilities._functions or {}
    return type(f.readfile) == "function" and type(f.writefile) == "function" and type(f.isfile) == "function"
end

function Storage:_fail(message)
    self.capabilities.storage.status = "Failed"
    self.capabilities.storage.detail = message
    self.log(message)
    return false, message
end

function Storage:_exists(path)
    local ok, exists = pcall(self.capabilities._functions.isfile, path)
    if not ok or type(exists) ~= "boolean" then return nil, "File availability check failed; existing files preserved." end
    return exists
end

function Storage:_decode(text)
    if type(text) ~= "string" or #text == 0 or #text > self.MAX_BYTES then return nil, "JSON is empty or exceeds the size limit." end
    if not self.http then return nil, "JSON service unavailable." end
    local ok, value = pcall(function() return self.http:JSONDecode(text) end)
    if not ok or type(value) ~= "table" then return nil, "Malformed JSON." end
    return value
end

function Storage:_encode(value)
    if not self.http then return nil, "JSON service unavailable." end
    local ok, text = pcall(function() return self.http:JSONEncode(value) end)
    if not ok or type(text) ~= "string" or #text > self.MAX_BYTES then return nil, "JSON encoding failed or exceeds the size limit." end
    return text
end

function Storage:import(text)
    local data, err = self:_decode(text)
    if not data then return nil, err end
    local ok, reason = Config.validate(data)
    if not ok then return nil, "Invalid configuration: " .. tostring(reason) end
    return Util.copy(data)
end

function Storage:export(data)
    local ok, err = Config.validate(data)
    if not ok then return nil, "Invalid configuration: " .. tostring(err) end
    return self:_encode(data)
end

function Storage:_read(path)
    local exists, err = self:_exists(path)
    if exists == nil then return nil, err end
    if not exists then return nil, "missing" end
    local ok, raw = pcall(self.capabilities._functions.readfile, path)
    if not ok or type(raw) ~= "string" then return nil, "Local file read failed; existing files preserved.", true end
    return raw
end

function Storage:load()
    if not self:_available() then return nil, "Persistent storage unavailable; profiles stay in memory until exported." end
    local raw, err = self:_read(self.FILES.saved)
    local missing = not raw and err == "missing"
    local data, reason
    if raw then data, reason = self:import(raw) else reason = err end
    if data then
        self.blocked, self.partialWrites[self.FILES.saved] = false, nil
        self.capabilities.storage.status = "Available but unverified"
        self.capabilities.storage.detail = "Saved JSON read and validated; next Save verifies writes."
        return data
    end
    local backup = self:_read(self.FILES.backup)
    local recovered = backup and self:import(backup)
    if missing then
        self.blocked, self.partialWrites[self.FILES.saved] = false, nil
        if not recovered then return nil, "No saved V3 configuration." end
        local message = "Loaded the validated backup. Save to restore the missing layout file."
        self.capabilities.storage.status, self.capabilities.storage.detail = "Available but unverified", message
        return recovered, message
    end
    self.blocked = true
    local message = recovered and "Loaded valid backup in memory. Damaged saved file preserved; export before repairing storage manually." or "Saved configuration could not be validated. Original file preserved; Save is blocked until it is repaired or moved manually."
    self:_fail(message)
    return recovered, reason or message
end

function Storage:_verifiedWrite(path, raw)
    local ok = pcall(self.capabilities._functions.writefile, path, raw)
    if not ok then return false end
    local readOk, actual = pcall(self.capabilities._functions.readfile, path)
    return readOk and actual == raw
end

function Storage:_saveDocument(raw, files, decode, requested, expected)
    -- Validate every existing primary before any overwrite, including saves before load.
    local path = files.saved
    local previous, readError = self:_read(path)
    if not previous and readError ~= "missing" then return false, readError end
    local observed = previous
    local retryingFirstWrite = previous ~= nil and previous == self.partialWrites[path]
    if not retryingFirstWrite then self.partialWrites[path] = nil end
    if previous then
        local previousData = decode(self, previous)
        if not previousData then
            if not retryingFirstWrite then return false, "Save blocked. Existing configuration is invalid and has been preserved.", true end
            previous = nil
        elseif Util.equal(previousData, requested) then
            return true, nil, false, true
        elseif expected and not Util.equal(previousData, expected) then
            local subject = files == self.FILES and "Saved layouts" or "Saved editor preferences"
            return false, subject .. " changed in another session. Rejoin to load them."
        end
    end
    if not self:_verifiedWrite(files.pending, raw) then return false, "Save failed while staging configuration. Previous save preserved.", false end
    local latest, latestError = self:_read(path)
    if latest ~= observed or (not latest and latestError ~= "missing") then
        return false, "The saved configuration changed during Save. The current file was preserved."
    end
    local olderBackup
    if previous then
        local backupError
        olderBackup, backupError = self:_read(files.backup)
        if not olderBackup and backupError ~= "missing" then return false, backupError end
        if not self:_verifiedWrite(files.backup, previous) then
            if olderBackup then self:_verifiedWrite(files.backup, olderBackup) end
            return false, "Save failed while preserving backup. Previous save preserved.", false
        end
    end
    if not self:_verifiedWrite(path, raw) then
        if previous then
            if self:_verifiedWrite(path, previous) then
                if olderBackup and olderBackup ~= previous then self:_verifiedWrite(files.backup, olderBackup) end
                return false, "Save failed during final write. The previous configuration was restored and verified.", false
            end
            return false, "Save failed during final write. Previous backup and staged data remain available.", false
        end
        local incomplete = self:_read(path)
        if incomplete and #incomplete < #raw and raw:sub(1, #incomplete) == incomplete then
            -- A verified staged copy exists. Retry can replace only this exact incomplete first write.
            self.partialWrites[path] = incomplete
        else
            self.partialWrites[path] = nil
        end
        return false, "First save could not be verified. Staged data remains available.", false
    end
    self.partialWrites[path] = nil
    local remove = self.capabilities._functions.delfile
    if type(remove) == "function" then pcall(remove, files.pending) end
    return true
end

function Storage:save(data, expected)
    local raw, err = self:export(data)
    if not raw then return false, err end
    if not self:_available() then return false, "Checkpoint is in memory only. Export JSON for a durable copy.", true end
    local saved, reason, blocked, unchanged = self:_saveDocument(raw, self.FILES, self.import, data, expected)
    if blocked ~= nil or saved then self.blocked = blocked == true end
    if not saved then return self:_fail(reason) end
    self.capabilities.storage.status = "Supported and verified"
    if unchanged then
        self.capabilities.storage.detail = "Existing saved JSON was validated. The previous backup was retained."
        return true, "Layout is already saved."
    end
    self.capabilities.storage.detail = "Last Save wrote and read back validated JSON."
    return true, "Profile persisted locally and verified by readback. Automatic execution must be configured separately."
end

function Storage:_decodeEditorPreferences(raw)
    local data, reason = self:_decode(raw)
    if not data then return nil, reason end
    local valid, problem = Config.validateEditorPreferences(data)
    if not valid then return nil, problem end
    return data
end

function Storage:loadEditorPreferences()
    if not self:_available() then return nil, "Editor preferences will apply for this session only." end
    local files = self.EDITOR_FILES
    local raw, reason = self:_read(files.saved)
    local missing = not raw and reason == "missing"
    local data = raw and self:_decodeEditorPreferences(raw)
    if data then
        self.partialWrites[files.saved] = nil
        return data
    end
    local backupRaw = self:_read(files.backup)
    local backup = backupRaw and self:_decodeEditorPreferences(backupRaw)
    if missing then
        self.partialWrites[files.saved] = nil
        if backup then return backup, "Loaded editor preferences from the validated backup. The primary file is missing." end
        return nil
    end
    if backup then return backup, "Loaded editor preference backup. The original file was preserved." end
    return nil, "Editor preferences could not be read. The original file was preserved."
end

function Storage:saveEditorPreferences(data, expected)
    local valid, reason = Config.validateEditorPreferences(data)
    if not valid then return false, reason end
    if not self:_available() then return false, "Local file storage is unavailable." end
    local raw, err = self:_encode(data)
    if not raw then return false, err end
    local saved, problem = self:_saveDocument(raw, self.EDITOR_FILES, self._decodeEditorPreferences, data, expected)
    return saved, problem
end

function Storage:draft(state, context)
    context = Util.copy(context or self.context)
    local path = self:_draftPath(context)
    if context and path == self.FILES.draft then return false, "Invalid draft context." end
    state = Util.copy(state)
    if type(state) == "table" and context then
        if state.context and not Util.equal(state.context, context) then return false, "Draft context changed before recording; previous recovery preserved." end
        state.context = context
    end
    local valid, reason = validateState(state)
    if not valid then return false, "Invalid draft: " .. tostring(reason) end
    if not self:_available() then return false, "Draft recovery unavailable without local storage." end
    return self:_mutateDraft(path, self._writeDraft, state)
end

function Storage:_mutateDraft(path, operation, value)
    if self.draftOperations[path] then return false, "Draft storage is busy. Try again after the current write.", true end
    self.draftOperations[path] = true
    local ran, ok, message = pcall(operation, self, path, value)
    self.draftOperations[path] = nil
    if not ran then return false, "Draft storage operation could not complete." end
    return ok, message
end

function Storage:_writeDraft(path, state)
    local raw, err = self:_encode({version = Config.VERSION, draft = true, state = state})
    if not raw then return false, err end
    -- A corrupt draft is also user data; keep it until explicitly cleared.
    local previous, readError = self:_read(path)
    if not previous and readError ~= "missing" then return false, readError end
    if previous then
        local old = self:_decode(previous)
        if not old or old.version ~= Config.VERSION or (old.draft ~= false and (old.draft ~= true or not validateState(old.state))) then return false, "Damaged draft preserved; clear it explicitly before recording another draft." end
        if old.draft == true and not Util.equal(old.state.context, state.context) then return false, "Recovery draft from another context preserved; discard it explicitly before recording another draft." end
    end
    if not self:_verifiedWrite(path, raw) then
        if previous then pcall(self.capabilities._functions.writefile, path, previous) end
        return false, "Draft write failed. Saved profiles are preserved."
    end
    return true, "Unsaved draft recorded separately from profiles."
end

function Storage:loadDraft(context)
    if not self:_available() then return nil, "Draft recovery unavailable without local storage." end
    context = Util.copy(context or self.context)
    local path = self:_draftPath(context)
    if context and path == self.FILES.draft then return nil, "Invalid draft context." end
    if self.draftOperations[path] then return nil, "Draft update in progress." end
    local raw, err, unreadable = self:_read(path)
    if not raw then return nil, err, unreadable end
    local value, reason = self:_decode(raw)
    if not value then return nil, reason, true end
    if self:_foreignDraft(value, context) then return nil, "Draft belongs to another context." end
    if value.version == Config.VERSION and value.draft == false then return nil, "No recoverable draft." end
    if value.version ~= Config.VERSION or value.draft ~= true then return nil, "Incompatible draft.", true end
    local valid, why = validateState(value.state)
    if not valid then return nil, "Invalid draft: " .. tostring(why), true end
    if context and not Util.equal(value.state.context, context) then return nil, "Draft context is missing or invalid.", true end
    return Util.copy(value.state)
end

function Storage:clearDraft(context)
    if not self:_available() then return false, "Draft storage unavailable." end
    context = Util.copy(context or self.context)
    local path = self:_draftPath(context)
    if context and path == self.FILES.draft then return false, "Invalid draft context." end
    return self:_mutateDraft(path, self._clearDraft, context)
end

function Storage:_clearDraft(path, context)
    local exists, err = self:_exists(path)
    if exists == nil then return false, err end
    if not exists then return true, "No draft to clear." end
    if context then
        local raw = self:_read(path)
        local value = raw and self:_decode(raw)
        if self:_foreignDraft(value, context) then
            return false, "Draft belongs to another context and was preserved."
        end
    end
    local remove = self.capabilities._functions.delfile
    if type(remove) ~= "function" then
        local raw, encodeError = self:_encode({version = Config.VERSION, draft = false})
        if not raw then return false, encodeError end
        if self:_verifiedWrite(path, raw) then return true, "Draft discarded; saved profiles preserved." end
        return false, "Draft could not be discarded."
    end
    local ok = pcall(remove, path)
    local remaining = self:_exists(path)
    if not ok or remaining ~= false then return false, "Draft could not be deleted." end
    return true, "Draft discarded; saved profiles preserved."
end

function Storage:copy(text)
    if type(text) ~= "string" or #text > self.MAX_BYTES then return false, "Invalid clipboard content." end
    if type(self.capabilities._clipboard) ~= "function" then return false, "Clipboard unavailable; manually copy the JSON field." end
    local called, accepted = pcall(self.capabilities._clipboard, text)
    local ok = called and accepted ~= false
    self.capabilities.clipboard.status = ok and "Supported and verified" or "Failed"
    self.capabilities.clipboard.detail = ok and "Clipboard API accepted the export; paste to verify destination." or "Clipboard call failed; manually copy the JSON field."
    return ok, self.capabilities.clipboard.detail
end

return Storage
end

-- Module: Transform
__factories["Transform"] = function(require)
-- Transforms write accessible GuiObject properties and verify the resulting layout.
local Util = require("Util")
local Discovery = require("Discovery")
local Coordinates = require("Coordinates")
local Geometry = require("Geometry")
local TransformOpacity = require("TransformOpacity")

local Transform = {}
Transform.__index = Transform

local MAX_RECT_ERROR = 1.5
local dimensionKeys = {"xs", "xo", "ys", "yo"}
local propertyNames = {"position", "size", "rotation", "transparency"}
local rectKeys = {"x", "y", "w", "h"}
local propertyOperations = {position = "move", size = "resize", rotation = "rotation", transparency = "transparency"}
local operationProperties = {move = "position", groupMove = "position", resize = "size", groupResize = "size",
    position = "position", size = "size", rotation = "rotation", rotationHandle = "rotation",
    groupRotate = "rotation", transparency = "transparency"}
local cached = {cached = true}
local integerOffsets

local function isA(object, class)
    local ok, result = pcall(function() return object:IsA(class) end)
    return ok and result
end

local function udim(value)
    return UDim2.new(value.xs, value.xo, value.ys, value.yo)
end

local function normalizedOffset(offset)
    if integerOffsets == nil then integerOffsets = UDim2.new(0, 0.5, 0, 0).X.Offset ~= 0.5 end
    if not integerOffsets then return offset end
    return math.floor(offset + 0.5)
end

local function validDimension(value)
    if type(value) ~= "table" then return false end
    for _, key in ipairs(dimensionKeys) do
        if not Util.finite(value[key]) or math.abs(value[key]) > Geometry.MAX_SIZE then return false end
    end
    return true
end

local function validEntry(entry)
    if type(entry) ~= "table" or not validDimension(entry.position) or not validDimension(entry.size) then return false end
    if entry.rotation ~= nil and (not Util.finite(entry.rotation) or math.abs(entry.rotation) > 36000) then return false end
    if entry.transparency ~= nil and (not Util.finite(entry.transparency) or entry.transparency < 0 or entry.transparency > 1) then return false end
    if entry.opacity ~= nil and (type(entry.opacity) ~= "table" or not Util.finite(entry.opacity.factor)
        or entry.opacity.factor < 0 or entry.opacity.factor > 1
        or (entry.opacity.scope ~= "element" and entry.opacity.scope ~= "contents")) then return false end
    return true
end

local function normalizeEntry(entry)
    local result = Util.copy(entry)
    result.position.xo, result.position.yo = normalizedOffset(result.position.xo), normalizedOffset(result.position.yo)
    result.size.xo, result.size.yo = normalizedOffset(result.size.xo), normalizedOffset(result.size.yo)
    return result
end

local function matchesProperty(actual, expected, property)
    local a, b = actual[property], expected[property]
    if b == nil or a == b then return true end
    if a == nil then return false end
    if property == "size" or property == "position" then
        for _, key in ipairs(dimensionKeys) do
            local tolerance = (key == "xs" or key == "ys") and 0.000001 or 0.0001
            if math.abs(a[key] - b[key]) > tolerance then return false end
        end
        return true
    end
    return math.abs(a - b) <= 0.0001
end

local function matchesProperties(actual, expected)
    if not actual then return false end
    for _, property in ipairs(propertyNames) do
        if not matchesProperty(actual, expected, property) then return false end
    end
    return true
end

local function assign(object, property, value)
    if property == "position" then object.Position = udim(value)
    elseif property == "size" then object.Size = udim(value)
    elseif property == "rotation" then object.Rotation = value
    else object.BackgroundTransparency = value end
end

local function write(object, entry, before)
    for _, property in ipairs(propertyNames) do
        if entry[property] ~= nil and (not before or not matchesProperty(before, entry, property)) then
            assign(object, property, entry[property])
        end
    end
    if not matchesProperties(Discovery.serialize(object), entry) then error("Requested properties were rejected") end
end

local function restoreProperties(object, entry)
    if not object.Parent then return true end
    local actual = Discovery.serialize(object)
    if not actual then return false end
    -- A rejected property must not prevent the other properties from being restored.
    for _, property in ipairs(propertyNames) do
        if entry[property] ~= nil and not matchesProperty(actual, entry, property) then
            pcall(assign, object, property, entry[property])
        end
    end
    return matchesProperties(Discovery.serialize(object), entry)
end

local function directScale(object)
    local factor = 1
    for _, child in ipairs(object:GetChildren()) do
        if isA(child, "UIScale") then factor = factor * child.Scale end
    end
    return factor
end

local function scales(object, root)
    local positionScale, current = 1, object.Parent
    while current and current ~= root do
        if isA(current, "GuiObject") then positionScale = positionScale * directScale(current) end
        current = current.Parent
    end
    return positionScale, positionScale * directScale(object)
end

local function effectiveDimensions(object, size, root, projected)
    local parent = object.Parent
    local parentSize = parent and ((projected and projected[parent]) or parent.AbsoluteSize)
    if not parentSize then return nil, nil end
    local positionScale, sizeScale = scales(object, root)
    local basisX, basisY = parentSize.X, parentSize.Y
    local constraint = tostring(object.SizeConstraint)
    if constraint == "Enum.SizeConstraint.RelativeXX" or constraint == "RelativeXX" then basisY = basisX end
    if constraint == "Enum.SizeConstraint.RelativeYY" or constraint == "RelativeYY" then basisX = basisY end
    local own = sizeScale / positionScale
    return basisX * size.xs * own + size.xo * sizeScale, basisY * size.ys * own + size.yo * sizeScale
end

local function supportedDimensions(object, width, height, root, originalSize, projected)
    if not Util.finite(width) or not Util.finite(height) or width <= 0 or height <= 0
        or width > Geometry.MAX_SIZE or height > Geometry.MAX_SIZE then return false end
    if width >= Geometry.MIN_SIZE and height >= Geometry.MIN_SIZE then return true end
    local originalWidth, originalHeight = effectiveDimensions(object, originalSize, root, projected)
    return Util.finite(originalWidth) and Util.finite(originalHeight)
        and width >= Geometry.minimumSize(originalWidth) and height >= Geometry.minimumSize(originalHeight)
end

local function rectClose(actual, expected)
    if not actual then return false end
    for _, key in ipairs(rectKeys) do
        if math.abs(actual[key] - expected[key]) > MAX_RECT_ERROR then return false end
    end
    return true
end

local function sizeClose(actual, expected)
    return actual and math.abs(actual.w - expected.w) <= MAX_RECT_ERROR and math.abs(actual.h - expected.h) <= MAX_RECT_ERROR
end

local function changedProperties(actual, expected)
    local fields = {}
    for _, field in ipairs(propertyNames) do
        if not matchesProperty(actual, expected, field) then fields[field] = true end
    end
    return fields
end

local function frameReference(object, before, root)
    local positionScale, sizeScale = scales(object, root)
    local parent, anchor, rect = object.Parent, object.AnchorPoint, Coordinates.rect(object)
    if not Geometry.valid(rect) then error("Element geometry is unavailable") end
    if not Util.finite(positionScale) or positionScale <= 0 or not Util.finite(sizeScale) or sizeScale <= 0 then error("Invalid UIScale") end
    return {before = before, rect = rect, parent = parent, parentRect = Coordinates.rect(parent),
        anchorX = anchor.X, anchorY = anchor.Y, positionScale = positionScale, sizeScale = sizeScale}
end

local function fitRect(reference, target, after)
    local start, rect = reference.before, reference.rect
    local positionScale, sizeScale = reference.positionScale, reference.sizeScale
    after.size.xo = normalizedOffset(start.size.xo + (target.w - rect.w) / sizeScale)
    after.size.yo = normalizedOffset(start.size.yo + (target.h - rect.h) / sizeScale)
    if integerOffsets then
        local minimumWidth, minimumHeight = Geometry.minimumSize(rect.w), Geometry.minimumSize(rect.h)
        if target.w >= minimumWidth then
            local minOffset = start.size.xo + (minimumWidth - rect.w) / sizeScale
            after.size.xo = math.max(after.size.xo, math.ceil(minOffset - 0.000001))
        end
        if target.h >= minimumHeight then
            local minOffset = start.size.yo + (minimumHeight - rect.h) / sizeScale
            after.size.yo = math.max(after.size.yo, math.ceil(minOffset - 0.000001))
        end
    end
    local dw, dh = (after.size.xo - start.size.xo) * sizeScale, (after.size.yo - start.size.yo) * sizeScale
    after.position.xo = normalizedOffset(start.position.xo + (target.x - rect.x + reference.anchorX * dw) / positionScale)
    after.position.yo = normalizedOffset(start.position.yo + (target.y - rect.y + reference.anchorY * dh) / positionScale)
    return {x = rect.x + (after.position.xo - start.position.xo) * positionScale - reference.anchorX * dw,
        y = rect.y + (after.position.yo - start.position.yo) * positionScale - reference.anchorY * dh,
        w = rect.w + dw, h = rect.h + dh}
end

function Transform.new(discovery, log)
    local self = setmetatable({discovery = discovery, log = log or function() end, tracked = {}, pendingByObject = {},
        receipts = setmetatable({}, {__mode = "k"}), safe = false, destroyed = false}, Transform)
    self.opacity = TransformOpacity.new(discovery, function(key)
        local entry = self.tracked[key]
        return entry and entry.transparency
    end)
    return self
end

function Transform:_record(key, entry)
    local record = self.discovery:get(key)
    if record and not record.descriptor.ambiguous then return record end
    if not entry or not entry.descriptor then return nil end
    return self.discovery:match(entry.descriptor)
end

function Transform:_allowed(record, operation, entry, options)
    if not record or not record.object.Parent then return false, "Element is missing" end
    if not options or not options.cached then self.discovery:_classify(record) end
    if record.descriptor.ambiguous then return false, record.reason end
    local field = operationProperties[operation]
    local hardReason = field and record.managedProperties and record.managedProperties[field]
    if hardReason then return false, hardReason end
    local capability = record.capabilities and record.capabilities[operation]
    local experimental = capability and capability.experimental or (not capability and record.experimental)
    if experimental then
        if self.safe or (options and options.safe) then return false, "Safe Mode blocks experimental overrides" end
        local suspended = record.suspendedOperations and record.suspendedOperations[field]
        if suspended or (not capability and record.experimentalSuspended) then return false, capability and capability.reason or record.reason end
        local savedApproval = options and options.experimental and entry and entry.experimental == true
        if savedApproval and options.deferApproval then return true end
        if savedApproval then
            self.discovery.approved[record.key] = true
            record.experimentalApproved = true
            self.discovery:_classify(record)
            capability = record.capabilities and record.capabilities[operation]
        end
    end
    if capability then return capability.supported == true, capability.reason end
    if not record.editable then return false, record.reason or "Unsupported transformation" end
    return true
end

function Transform:_failed(record, reason, fields, scriptOverwrite, geometryMismatch, requested, actual)
    if scriptOverwrite then
        record.overwrittenProperties = record.overwrittenProperties or {}
        for field in pairs(fields) do record.overwrittenProperties[field] = true end
    elseif geometryMismatch and record.layoutController then
        if record.observedGeometryController ~= record.layoutController then record.observedGeometryBlocks = nil end
        record.observedGeometryController = record.layoutController
        record.observedGeometryBlocks = record.observedGeometryBlocks or {}
        for field in pairs(fields) do
            record.observedGeometryBlocks[field] = "The layout did not honor this adjustment. Select the parent to edit the bar."
        end
    end
    self.discovery:_classify(record)
    for field in pairs(fields) do
        local cap = record.capabilities and record.capabilities[propertyOperations[field]]
        if scriptOverwrite or (cap and cap.experimental) then
            record.operationFailures = record.operationFailures or {}
            record.operationFailures[field] = (record.operationFailures[field] or 0) + 1
            if record.operationFailures[field] >= 3 then
                record.suspendedOperations = record.suspendedOperations or {}
                record.suspendedOperations[field] = true
            end
        end
    end
    self.discovery:_classify(record)
    record.lastFailure = {reason = tostring(reason), requested = requested, actual = actual}
    local label = record.suspendedOperations and next(record.suspendedOperations) and "Experimental override suspended" or "Transform failed"
    self.log(label .. " (" .. tostring(record.object.Name) .. "): " .. tostring(reason):sub(1, 160))
end

function Transform:_operation(record, before, after)
    return {record = record, before = before, after = after, previousTracked = self.tracked[record.key],
        previousReceipt = self.receipts[record.object], previousApproval = self.discovery.approved[record.key]}
end

local function portableEntry(record, before, previous)
    local entry = previous and Util.copy(previous) or {position = before.position, size = before.size}
    entry.descriptor = record.descriptor
    if record.experimentalApproved then entry.experimental = true end
    return entry
end

function Transform:_rollback(operations)
    local rollbacks, restored = {}, true
    for index = #operations, 1, -1 do
        local operation = operations[index]
        local record, object = operation.record, operation.record.object
        local original = {}
        for _, property in ipairs(propertyNames) do
            if not matchesProperty(operation.before, operation.after, property) then original[property] = operation.before[property] end
        end
        if not restoreProperties(object, original) then
            restored = false
            self.log("Original properties could not be restored for " .. tostring(object.Name))
        end
        if operation.appearance and not self.opacity:rollback(operation.appearance) then restored = false end
        self.tracked[record.key] = operation.previousTracked
        self.receipts[object] = operation.previousReceipt
        if operation.setApproval and self.discovery.approved[record.key] ~= operation.previousApproval then
            self.discovery.approved[record.key] = operation.previousApproval
            self.discovery:_classify(record)
        end
        rollbacks[record.key] = operation.previousTracked or false
    end
    return rollbacks, restored
end

function Transform:_store(operation)
    local record = operation.record
    local portable = operation.portable or operation.after
    self.tracked[record.key] = not operation.removeTracked and portable or nil
    self.receipts[record.object] = operation.receipt or portable
    if operation.appearance then self.opacity:commit(operation.appearance) end
    if operation.setApproval then
        self.discovery.approved[record.key] = operation.setApproval == "grant" and true or nil
        self.discovery:_classify(record)
    end
end

function Transform:_writeBatch(operations, deferStore)
    for index, operation in ipairs(operations) do
        local ok, problem = pcall(write, operation.record.object, operation.after, operation.before)
        if not ok then
            local written = {}
            for i = 1, index do written[i] = operations[i] end
            local overwritten = tostring(problem):find("Requested properties were rejected", 1, true) ~= nil
            local observed = Discovery.serialize(operation.record.object)
            local fields = changedProperties(overwritten and observed or operation.before, operation.after)
            local _, restored = self:_rollback(written)
            self:_failed(operation.record, problem, fields, overwritten)
            return false, restored and "Transform rejected. The selection was restored." or "Transform rejected. Some original properties could not be restored."
        end
    end
    for _, operation in ipairs(operations) do
        if operation.appearance then
            local ok, problem = pcall(self.opacity.write, self.opacity, operation.appearance)
            if not ok then
                self.opacity:markFailed(operation.appearance)
                self:_failed(operation.record, problem, {})
                local _, restored = self:_rollback(operations)
                return false, restored and "The appearance adjustment was rejected. The previous appearance was restored."
                    or "The appearance adjustment was rejected and could not be fully restored."
            end
        end
    end
    if not deferStore then
        for _, operation in ipairs(operations) do self:_store(operation) end
    end
    return true
end

function Transform:_observation(operation)
    local object, reference = operation.record.object, operation.reference
    if not object.Parent then return "An element disappeared during editing.", {}, "environment" end
    local observed = Discovery.serialize(object)
    if not observed then return "The resulting GUI properties could not be read.", {}, "environment" end
    local appearance = operation.appearanceExpected or operation.appearance
    if self.opacity:property(appearance, object, "BackgroundTransparency") then
        observed.transparency = operation.after.transparency
    end
    if operation.appearance and not self.opacity:matches(operation.appearance) then
        self.opacity:markFailed(operation.appearance)
        return "The game replaced an opacity adjustment.", {}, "appearance"
    end
    local changed = changedProperties(observed, operation.after)
    if next(changed) then
        return "The game replaced the requested properties.", changed, "overwrite", operation.expectedRect and Coordinates.rect(object)
    end
    local expectedAngle = operation.after.rotation or (reference and reference.before.rotation)
    if operation.expectedRect and expectedAngle and math.abs(Geometry.angleDelta(expectedAngle, object.Rotation)) > 0.001 then
        return "The element rotated during editing.", {}, "environment"
    end
    local actual, expected = Coordinates.rect(object), operation.expectedRect
    if expected and operation.after.rotation then
        local angle = object.AbsoluteRotation
        if Util.finite(angle) and math.abs(Geometry.angleDelta(operation.after.rotation, angle)) > 0.05 then
            return "The rendered angle did not match the requested rotation.", {rotation = true}, "geometry", actual
        end
    end
    if expected and operation.verify == "position" and actual then
        expected = {x = expected.x - reference.anchorX * (actual.w - expected.w),
            y = expected.y - reference.anchorY * (actual.h - expected.h), w = actual.w, h = actual.h}
    end
    local matches = not expected or (operation.verify == "size" and sizeClose(actual, expected))
        or (operation.verify ~= "size" and rectClose(actual, expected))
    if not matches then
        local parentRect = Coordinates.rect(object.Parent)
        local ps, ss = scales(object, self.discovery.root)
        local anchor = object.AnchorPoint
        if object.Parent ~= reference.parent or (operation.verify ~= "size" and reference.parentRect and not rectClose(parentRect, reference.parentRect))
            or math.abs(ps - reference.positionScale) > 0.001 or math.abs(ss - reference.sizeScale) > 0.001
            or anchor.X ~= reference.anchorX or anchor.Y ~= reference.anchorY then
            return "The parent layout changed during editing.", {}, "environment", actual
        end
        local fields = operation.verify == "size" and {size = true}
            or operation.verify == "position" and {position = true} or {position = true, size = true}
        return "The resulting geometry differed from the requested adjustment.", fields, "geometry", actual
    end
    if operation.checkSize then
        local width, height = effectiveDimensions(object, operation.after.size, self.discovery.root)
        local rect = Coordinates.rect(object)
        if not rect or not supportedDimensions(object, width, height, self.discovery.root, operation.record.baseline.size)
            or math.abs(rect.w - width) > MAX_RECT_ERROR or math.abs(rect.h - height) > MAX_RECT_ERROR then
            return "The layout did not honor the requested dimensions.", {size = true}, "geometry", rect
        end
    end
end

function Transform:_finish(job, cancellation, early)
    local jobs = self.pendingStabilization
    if not jobs or not jobs[job] then return true end
    local reason, failures, onlyGeometry = cancellation, {}, true
    if not reason then
        for _, operation in ipairs(job.operations) do
            local ok, problem, fields, kind, actual = pcall(self._observation, self, operation)
            if not ok then problem, fields, kind = "The resulting GUI geometry could not be read.", {}, "environment" end
            if problem then
                reason = reason or problem
                onlyGeometry = onlyGeometry and kind == "geometry"
                failures[#failures + 1] = {record = operation.record, problem = problem, fields = fields, kind = kind,
                    requested = operation.expectedRect, actual = actual}
            end
        end
    end
    if early and reason and onlyGeometry then return nil end
    jobs[job] = nil
    for _, operation in ipairs(job.operations) do self.pendingByObject[operation.record.object] = nil end
    if not next(jobs) then self.pendingStabilization = nil end
    if self.interactivePending == job then self.interactivePending = nil end
    for _, failure in ipairs(failures) do
        if failure.record.object.Parent and failure.kind ~= "environment" then
            self:_failed(failure.record, failure.problem, failure.fields, failure.kind == "overwrite", failure.kind == "geometry",
                failure.requested, failure.actual)
        end
    end
    local rollbacks
    if reason then
        local restored
        rollbacks, restored = self:_rollback(job.operations)
        for _, operation in ipairs(job.operations) do
            -- A failed saved request is still handled for this instance. Structural
            -- refreshes can restore recreated instances without retrying an old one.
            if not cancellation and not job.replay and operation.receipt and operation.record.object.Parent then
                self.receipts[operation.record.object] = operation.receipt
            end
        end
        if not restored then reason = reason .. " Some original properties could not be restored." end
        if not cancellation then self.log(reason) end
    elseif job.replay then
        for _, operation in ipairs(job.operations) do self:_store(operation) end
    end
    if job.callback then
        local ok, problem = pcall(job.callback, not reason, reason, rollbacks)
        if not ok then self.log("Adjustment completion could not be reported: " .. tostring(problem):sub(1, 160)) end
    elseif reason and not cancellation and self.onChanged then pcall(self.onChanged, rollbacks) end
    return not reason
end

function Transform:_schedule()
    if self.stabilizationScheduled or not self.pendingStabilization then return end
    local early = self.interactivePending
    if early and early.earlyChecked then early = nil end
    if early then
        for _, operation in ipairs(early.operations) do
            local capabilities = operation.record.capabilities
            for field in pairs(operation.after) do
                local capability = capabilities and capabilities[field]
                if capability and capability.experimental then early = nil; break end
            end
            if not early then break end
        end
    end
    local scheduled = {}
    if early then scheduled[early] = early.revision
    else for job in pairs(self.pendingStabilization) do scheduled[job] = job.revision end end
    local function observe()
        self.stabilizationScheduled = false
        if self.destroyed then return end
        for job, revision in pairs(scheduled) do
            if job.revision == revision then
                if job == early then job.earlyChecked = true end
                self:_finish(job, nil, job == early)
            end
        end
        self:_schedule()
    end
    self.stabilizationScheduled = true
    if task and task.delay then task.delay(early and 0.04 or 0.10, observe) else observe() end
end

function Transform:_queue(job, deferSchedule)
    self.pendingStabilization = self.pendingStabilization or {}
    self.pendingStabilization[job] = true
    job.revision = (job.revision or 0) + 1
    for _, operation in ipairs(job.operations) do self.pendingByObject[operation.record.object] = job end
    if not deferSchedule then self:_schedule() end
end

function Transform:_supersedePending()
    self:cancelTransaction()
    local pending = self.pendingStabilization
    for job in pairs(pending or {}) do self:_finish(job, "Layout superseded.") end
end

function Transform:beginTransaction()
    if self.destroyed or self.transaction or self.interactivePending then return false end
    self.transaction = {initial = {}, operations = {}, objectsByKey = {}}
    return true
end

function Transform:_recordUpdates(operations)
    for _, operation in ipairs(operations) do
        local transaction, object = self.transaction, operation.record.object
        local initial = transaction.initial[object]
        if not initial then
            initial = operation
            transaction.initial[object] = initial
            transaction.operations[#transaction.operations + 1] = initial
        else
            initial.after, initial.expectedRect, initial.verify = operation.after, operation.expectedRect, operation.verify
            initial.portable, initial.checkSize, initial.forcePortable = operation.portable, operation.checkSize, operation.forcePortable
            initial.appearance = self.opacity:merge(initial.appearance, operation.appearance)
        end
    end
end

function Transform:endTransaction(callback)
    local transaction = self.transaction
    self.transaction = nil
    if not transaction then return false end
    local operations = {}
    for _, operation in ipairs(transaction.operations) do
        local meaningfulOpacity = self.opacity:changed(operation.appearance)
            or (operation.forcePortable and not Util.equal(operation.previousTracked, operation.portable))
        if not meaningfulOpacity and matchesProperties(operation.before, operation.after)
            and (not operation.previousTracked or Util.equal(operation.previousTracked, operation.portable or operation.after))
            and matchesProperties(Discovery.serialize(operation.record.object), operation.after) then
            local record = operation.record
            self.tracked[record.key], self.receipts[record.object] = operation.previousTracked, operation.previousReceipt
        else
            operations[#operations + 1] = operation
        end
    end
    if #operations == 0 then
        if callback then callback(true) end
    else
        local job = {operations = operations, callback = callback}
        self.interactivePending = job
        self:_queue(job)
    end
    return true
end

function Transform:cancelTransaction()
    local transaction = self.transaction
    self.transaction = nil
    if transaction then
        local _, restored = self:_rollback(transaction.operations)
        return true, restored
    end
    if self.interactivePending then
        self:_finish(self.interactivePending, "The adjustment was canceled.")
        return true
    end
    return false
end

function Transform:capture()
    local result = {}
    for key, entry in pairs(self.tracked) do
        if self:_record(key, entry) then result[key] = Util.copy(entry) end
    end
    return result
end

function Transform:selectionRects(keys, editableOnly, operation)
    if type(editableOnly) == "string" then operation, editableOnly = editableOnly, true end
    local seen, records, recordKeys, skipped = {}, {}, {}, 0
    for _, key in ipairs(keys or {}) do
        if not seen[key] then
            seen[key] = true
            local record = self.discovery:get(key)
            local supportsEdit = not editableOnly or (operation and self:_allowed(record, operation, nil, cached))
                or (not operation and (self:_allowed(record, "move", nil, cached) or self:_allowed(record, "resize", nil, cached)))
            if record and supportsEdit then
                records[#records + 1], recordKeys[record.object] = record.object, key
            else skipped = skipped + 1 end
        end
    end
    local rects, roots = {}, {}
    local members = #records > 1 and Geometry.roots(records, function(item) return item.Parent end) or records
    for _, object in ipairs(members) do
        local rect = Coordinates.rect(object)
        if Geometry.valid(rect) then rects[#rects + 1], roots[#roots + 1] = rect, recordKeys[object]
        else skipped = skipped + 1 end
    end
    return rects, roots, skipped
end

local function sameDirectJob(job, records)
    if not job or not job.direct or #job.operations ~= #records then return false end
    for index, record in ipairs(records) do
        if job.operations[index].record ~= record then return false end
    end
    return true
end

function Transform:setRects(keys, rects, operation)
    if self.destroyed then return false, "Transform controller is closed." end
    if #keys ~= #rects or #keys == 0 then return false, "No valid selection." end
    local transaction, records, selected = self.transaction, {}, {}
    for _, key in ipairs(keys) do
        local record = self.discovery:get(key)
        if not record or not record.object.Parent then return false, "An element is missing." end
        if record.descriptor.ambiguous then return false, record.reason or "This layer does not have a unique identity." end
        if transaction then
            local original = transaction.objectsByKey[key]
            if original and original ~= record.object then return false, "An element was recreated during editing." end
            transaction.objectsByKey[key] = record.object
        end
        if selected[record.object] then return false, "Repeated selection." end
        records[#records + 1], selected[record.object] = record, true
    end
    local direct = not transaction and self.pendingByObject[records[1].object] or nil
    if not sameDirectJob(direct, records) then direct = nil end
    local operations = {}
    for i, record in ipairs(records) do
        local object, target = record.object, rects[i]
        local pending = self.pendingByObject[object]
        if pending and pending ~= direct then self:_finish(pending) end
        local previous = transaction and transaction.initial[object] or (direct and direct.operations[i])
        if not previous then
            local parent = object.Parent
            while parent and parent ~= self.discovery.root do
                if selected[parent] then return false, "A selected parent already transforms its children." end
                parent = parent.Parent
            end
            self.discovery:_classify(record)
        end
        if not Geometry.valid(target) then return false, "Invalid dimensions." end
        for _, axis in ipairs(rectKeys) do
            if math.abs(target[axis]) > Geometry.MAX_SIZE then return false, "Invalid dimensions." end
        end
        local ok, mutation = pcall(function()
            local before = Discovery.serialize(object)
            if not before then error("Properties inaccessible") end
            if previous and not matchesProperties(before, previous.after) then
                local message = "The game replaced the adjustment during editing"
                self:_failed(record, message, changedProperties(before, previous.after), true)
                error(message)
            end
            -- Intermediate Roblox AbsolutePosition/AbsoluteSize can be one layout frame behind writes.
            local reference = previous and previous.reference or frameReference(object, before, self.discovery.root)
            if object.Parent ~= reference.parent then error("The element was moved to a different parent during editing") end
            local resizeMode = operation == "resize" or operation == "groupResize"
            local resizeRequested = math.abs(target.w - reference.rect.w) > 0.001 or math.abs(target.h - reference.rect.h) > 0.001
            local moveRequested = math.abs(target.x - reference.rect.x) > 0.001 or math.abs(target.y - reference.rect.y) > 0.001
            local useSize = resizeRequested or resizeMode or (previous and previous.after.size ~= nil)
            local canMove, moveReason = self:_allowed(record, operation == "groupMove" and "groupMove" or "move", nil, cached)
            if (operation == "move" or operation == "groupMove" or (not resizeMode and moveRequested)) and not canMove then
                error(moveReason or "Independent movement is unavailable")
            end
            if useSize then
                local canResize, resizeReason = self:_allowed(record, operation == "groupResize" and "groupResize" or "resize", nil, cached)
                if not canResize then error(resizeReason or "Independent resizing is unavailable") end
            end
            if not useSize and not canMove then error(moveReason or "Independent movement is unavailable") end
            local floorWidth = resizeMode and Geometry.minimumSize(reference.rect.w) or Geometry.MIN_SIZE
            local floorHeight = resizeMode and Geometry.minimumSize(reference.rect.h) or Geometry.MIN_SIZE
            if useSize and ((target.w + 0.001 < floorWidth and math.abs(target.w - reference.rect.w) > 0.001)
                or (target.h + 0.001 < floorHeight and math.abs(target.h - reference.rect.h) > 0.001)) then
                error("The target is below its minimum editable size")
            end
            local after = {position = Util.copy(before.position), size = Util.copy(before.size)}
            local expected = fitRect(reference, target, after)
            local usePosition = canMove and (moveRequested or not useSize or (previous and previous.after.position ~= nil)
                or not matchesProperty(reference.before, after, "position"))
            if not validEntry(after) or (usePosition and not rectClose(expected, target)) or (useSize and not sizeClose(expected, target)) then
                error("This scale cannot represent the requested geometry accurately")
            end
            if not usePosition then after.position = nil end
            if not useSize then after.size = nil end
            local result = self:_operation(record, before, after)
            local prior = result.previousTracked
            if previous then prior = previous.previousTracked end
            result.portable = portableEntry(record, reference.before, prior)
            if not matchesProperty(reference.before, after, "position") then result.portable.position = after.position end
            if not matchesProperty(reference.before, after, "size") then result.portable.size = after.size end
            result.reference, result.expectedRect = reference, Util.copy(target)
            result.verify = usePosition and (useSize and "bounds" or "position") or "size"
            return result
        end)
        if not ok then return false, tostring(mutation):gsub("^.-:%d+: ", "") end
        if direct or not matchesProperties(mutation.before, mutation.after) then operations[#operations + 1] = mutation end
    end
    if #operations == 0 then return true end
    local ok, reason = self:_writeBatch(operations)
    if not ok then return false, reason end
    if transaction then self:_recordUpdates(operations)
    elseif direct then
        for index, operation in ipairs(operations) do
            direct.operations[index].after, direct.operations[index].expectedRect = operation.after, operation.expectedRect
            direct.operations[index].portable, direct.operations[index].verify = operation.portable, operation.verify
        end
        self:_queue(direct)
    else self:_queue({operations = operations, direct = true}) end
    return true
end

function Transform:rotationSnapshot(keys)
    local rects, roots, skipped = self:selectionRects(keys)
    if #roots == 0 or skipped > 0 then return nil, "Select available layers to rotate." end
    local isGroup, members, visual = #roots > 1, {}, {}
    for index, key in ipairs(roots) do
        local record = self.discovery:get(key)
        local pending = self.pendingByObject[record.object]
        if pending then self:_finish(pending) end
        local allowed, reason = self:_allowed(record, isGroup and "groupRotate" or "rotationHandle")
        if not allowed then return nil, reason or "A selected layer cannot rotate here." end
        local before = Discovery.serialize(record.object)
        local ok, reference = pcall(frameReference, record.object, before, self.discovery.root)
        if not before or not ok then return nil, "A selected layer's rotation center is unavailable." end
        rects[index] = reference.rect
        members[index] = {record = record, reference = reference, center = Geometry.center(reference.rect)}
        visual[index] = Geometry.rotatedBounds(reference.rect, before.rotation)
    end
    return {keys = roots, members = members, pivot = Geometry.center(Geometry.bounds(visual)),
        isGroup = isGroup, angle = isGroup and 0 or members[1].reference.before.rotation,
        classificationRevision = self.discovery.classificationRevision}
end

function Transform:setRotation(snapshot, delta)
    if not self.transaction then return false, "Start a rotation gesture first." end
    if type(snapshot) ~= "table" or not Util.finite(delta) then return false, "The requested angle is unavailable." end
    local operations = {}
    local revision = self.discovery.classificationRevision
    local options = {cached = snapshot.classificationRevision == revision}
    delta = Geometry.angleDelta(0, delta)
    for _, member in ipairs(snapshot.members) do
        local record, reference = member.record, member.reference
        local object = record.object
        local current = self.discovery:get(record.key)
        if not current or current.object ~= object or object.Parent ~= reference.parent then
            return false, "A layer changed during rotation."
        end
        local allowed, reason = self:_allowed(current, snapshot.isGroup and "groupRotate" or "rotationHandle", nil, options)
        if not allowed then return false, reason or "A layer cannot rotate here." end
        local before = Discovery.serialize(object)
        if not before then return false, "The current angle is unavailable." end
        local prior = self.transaction.initial[object]
        if not prior and (not matchesProperty(before, reference.before, "rotation")
            or (snapshot.isGroup and not matchesProperty(before, reference.before, "position"))) then
            return false, "A layer changed before rotation began. Try again."
        end
        if prior and not matchesProperties(before, prior.after) then
            local message = "The game replaced the adjustment during editing."
            self:_failed(current, message, changedProperties(before, prior.after), true)
            return false, message
        end
        local original, rect = reference.before, reference.rect
        local angle = original.rotation + delta
        if math.abs(angle) > 360 then angle = Geometry.angleDelta(0, angle) end
        local after, expected = {rotation = angle}, rect
        if snapshot.isGroup then
            local center = Geometry.rotatePoint(member.center, snapshot.pivot, delta)
            local dx, dy = center.x - member.center.x, center.y - member.center.y
            local position, scale = Util.copy(original.position), reference.positionScale
            position.xo = normalizedOffset(position.xo + dx / scale)
            position.yo = normalizedOffset(position.yo + dy / scale)
            if not validDimension(position) or math.abs((position.xo - original.position.xo) * scale - dx) > MAX_RECT_ERROR
                or math.abs((position.yo - original.position.yo) * scale - dy) > MAX_RECT_ERROR then
                return false, "A layer's scale cannot represent this group rotation accurately."
            end
            after.position, expected = position, Geometry.translate(rect, dx, dy)
        end
        local mutation = self:_operation(current, before, after)
        local previous = mutation.previousTracked
        if prior then previous = prior.previousTracked end
        local portable = portableEntry(current, original, previous)
        if angle ~= original.rotation then portable.rotation = angle end
        if after.position and not matchesProperty(original, after, "position") then portable.position = after.position end
        mutation.portable = portable
        mutation.reference, mutation.expectedRect, mutation.verify = reference, expected, "position"
        if not matchesProperties(before, after) then operations[#operations + 1] = mutation end
    end
    snapshot.classificationRevision = revision
    local ok, reason = self:_writeBatch(operations)
    if ok then self:_recordUpdates(operations) end
    return ok, reason
end

function Transform:opacitySnapshot(keys, scope, canEdit)
    return self.opacity:snapshot(keys, scope, canEdit)
end

function Transform:opacityTargets(key)
    return self.opacity:targets(key)
end

function Transform:setOpacity(snapshot, factor)
    if not self.transaction then return false, "Start an opacity gesture first." end
    if type(snapshot) ~= "table" or not Util.finite(factor) or factor < 0 or factor > 1 then
        return false, "Choose an opacity from 0 to 100 percent."
    end
    local operations, edits = {}, {}
    local revision = self.discovery.revision
    local recheck = snapshot.revision ~= revision
    for _, group in ipairs(snapshot.groups) do
        local record = self.discovery:get(group.record.key)
        if not record or record.object ~= group.record.object or not record.object.Parent then return false, "A layer changed during editing." end
        local pending = self.pendingByObject[record.object]
        if pending then self:_finish(pending) end
        local before = Discovery.serialize(record.object)
        if not before then return false, "The selected layer is unavailable." end
        local prior = self.transaction.initial[record.object]
        if prior and prior.appearance and not self.opacity:matches(prior.appearance) then
            self.opacity:markFailed(prior.appearance)
            return false, "The game replaced an opacity adjustment."
        end
        if recheck then
            for _, target in ipairs(group.targets) do
                local owner = self.discovery:get(target.key)
                if not owner or owner.object ~= target.record.object or not target.object.Parent then
                    return false, "An appearance layer changed during editing."
                end
            end
        end
        local opacity = {factor = factor, scope = snapshot.scope, targets = group.keys}
        local operation = self:_operation(record, before, {})
        operation.portable = portableEntry(record, before, operation.previousTracked)
        operation.portable.opacity, operation.forcePortable = opacity, true
        operations[#operations + 1] = operation
        edits[#edits + 1] = {record = record, spec = opacity, targets = group.targets, canEdit = snapshot.canEdit}
    end
    snapshot.revision = revision
    local change, preparationError = self.opacity:prepare(edits)
    if not change or #operations == 0 then return false, preparationError or "There are no supported opacity surfaces." end
    if not self.opacity:changed(change) then return true end
    if not self.opacity:surfaceChanged(change) and factor == 1 then
        local existing = false
        for _, operation in ipairs(operations) do
            if operation.previousTracked and operation.previousTracked.opacity then existing = true; break end
        end
        if not existing then return true end
    end
    operations[1].appearance = change
    local ok, reason = self:_writeBatch(operations)
    if ok then self:_recordUpdates(operations) end
    return ok, reason
end

function Transform:_savedFields(record, before, entry, previous, options)
    local portable = normalizeEntry(entry or record.baseline)
    local raw, blocked = {}, nil
    local revoking = entry and entry.experimental == false
    local approval = {cached = true, experimental = options.experimental, deferApproval = true, safe = options.safe}
    for _, field in ipairs(propertyNames) do
        local value = portable[field]
        local prior = previous and previous[field]
        if value == nil and prior ~= nil and options.replace then value = record.baseline[field] end
        local old = record.baseline[field]
        if previous then old = prior end
        local scriptOwned = record.overwrittenProperties and record.overwrittenProperties[field] == true
        local revokeField = revoking and previous and previous.experimental == true and scriptOwned
        if revokeField then
            value = record.baseline[field]
            portable[field] = value
        end
        local requested = value ~= nil and (not options.delta or not Util.equal(old, value) or revokeField)
        if requested and (not revoking or not scriptOwned or revokeField) then
            local allowed, reason = self:_allowed(record, field, entry, approval)
            local owned = prior ~= nil and Util.equal(before[field], prior)
            local safeRestore = (not entry or revokeField) and owned and not (record.managedProperties and record.managedProperties[field])
            if allowed or safeRestore then raw[field] = value
            elseif not Util.equal(before[field], value) then blocked = blocked or reason or "A layout controls this property" end
        end
    end
    return raw, portable, blocked
end

function Transform:apply(layout, options)
    options = options or {}
    if self.destroyed or type(layout) ~= "table" then return 0, 0 end
    local applied, skipped, pending, projected = 0, 0, {}, {}
    if options.replace then
        self:_supersedePending()
        -- Permissions belong to the new checkpoint. Replacing it revokes absent approvals.
        for key in pairs(self.discovery.approved) do
            if not layout[key] or layout[key].experimental ~= true then
                self.discovery.approved[key] = nil
                local record = self.discovery:get(key)
                if record then self.discovery:_classify(record) end
            end
        end
        for key, entry in pairs(self.tracked) do
            if not layout[key] then
                local record = self:_record(key, entry)
                if record then
                    local before = Discovery.serialize(record.object)
                    if before then
                        self.discovery:_classify(record)
                        local original = self:_savedFields(record, before, nil, entry, {replace = true, delta = true})
                        local operation = self:_operation(record, before, original)
                        operation.removeTracked, operation.receipt = true, record.baseline
                        if self.opacity:hasScope(record.key) or original.transparency then
                            operation.appearance = self.opacity:prepare({{record = record, legacy = false}})
                        end
                        if not self:_writeBatch({operation}) then self.log("Original properties could not be restored for " .. tostring(record.object.Name)) end
                    end
                else self.opacity:forget(key) end
            end
        end
        for key in pairs(self.tracked) do if not layout[key] then self.tracked[key] = nil end end
    end
    for key, entry in pairs(layout) do
        local record = self:_record(key, entry)
        if options.onlyNew and record and Util.equal(self.receipts[record.object], entry) then
            -- The same request already ran for this instance.
            if entry.opacity then pending[#pending + 1] = {record = record, entry = entry, appearanceOnly = true} end
        elseif not validEntry(entry) then
            skipped = skipped + 1
            self.log("Skipped invalid layout properties")
        elseif not record then skipped = skipped + 1
        else pending[#pending + 1] = {record = record, entry = entry} end
    end
    table.sort(pending, function(a, b) return #a.record.descriptor.path < #b.record.descriptor.path end)
    for _, item in ipairs(pending) do
        local record, entry = item.record, item.entry
        local object = record.object
        local previous = self.pendingByObject[object]
        if previous then self:_finish(previous) end
        self.discovery:_classify(record)
        local before = Discovery.serialize(object)
        local after, portable, reason
        if before then
            if item.appearanceOnly then after, portable = {}, normalizeEntry(entry)
            else after, portable, reason = self:_savedFields(record, before, entry, self.tracked[record.key], options) end
        end
        local width, height
        local checkSize = after and after.size ~= nil and not Util.equal(after.size, record.baseline.size)
        if after then
            local dimensionsOK
            dimensionsOK, width, height = pcall(effectiveDimensions, object, after.size or before.size, self.discovery.root, projected)
            local ancestor, parentResized = object.Parent, false
            while ancestor and ancestor ~= self.discovery.root do
                if projected[ancestor] then parentResized = true break end
                ancestor = ancestor.Parent
            end
            if checkSize and (not dimensionsOK or not supportedDimensions(object, width, height, self.discovery.root, record.baseline.size, projected))
                and not parentResized then
                after.size, checkSize, width, height = nil, false, nil, nil
                reason = reason or "Saved dimensions fall outside the supported range"
            end
        end
        local appearance, appearanceError
        if before and (entry.opacity or self.opacity:hasScope(record.key) or after.transparency ~= nil) then
            appearance, appearanceError = self.opacity:prepare({{record = record, spec = entry.opacity,
                legacy = entry.transparency ~= nil and entry.transparency or false}}, options.onlyNew)
        end
        reason = reason or appearanceError
        if reason then skipped = skipped + 1; self.log("Skipped part of " .. tostring(object.Name) .. ": " .. reason) end
        local changedAppearance = appearance and (#appearance.writes > 0 or self.opacity:changed(appearance))
        if before and ((not reason and not item.appearanceOnly) or not matchesProperties(before, after) or changedAppearance) then
            local operation = self:_operation(record, before, after)
            operation.receipt, operation.checkSize, operation.portable = Util.copy(entry), checkSize, portable
            operation.appearance = appearance
            if entry.experimental == false then operation.setApproval = "revoke"
            elseif options.experimental and entry.experimental == true then operation.setApproval = "grant" end
            local ok, message = self:_writeBatch({operation})
            if ok then
                applied = applied + 1
                if Util.finite(width) and Util.finite(height) then projected[object] = {X = width, Y = height} end
                if self.transaction then self:_recordUpdates({operation})
                else self:_queue({operations = {operation}}, true) end
            else
                skipped = skipped + 1
                self.log(message)
            end
        else
            if not before then
                skipped = skipped + 1
                self.log("Skipped " .. tostring(object.Name) .. ": Properties inaccessible")
            else
                self.receipts[object] = Util.copy(entry)
                if entry.experimental == false then
                    self.discovery.approved[record.key] = nil
                    self.discovery:_classify(record)
                end
            end
        end
    end
    self:_schedule()
    return applied, skipped
end

function Transform:applyHistory(previous, desired, callback)
    if self.destroyed or self.transaction or self.interactivePending then return false end
    local changed = {}
    for key, entry in pairs(previous) do
        if not Util.equal(entry, desired[key]) then changed[key] = true end
    end
    for key in pairs(desired) do if not previous[key] then changed[key] = true end end
    local operations, opacityEdits, forgotten, skipped = {}, {}, {}, 0
    for key in pairs(changed) do
        local entry = desired[key]
        local record = self:_record(key, entry or previous[key])
        if not record or not record.object.Parent then
            skipped = skipped + 1
            forgotten[#forgotten + 1] = key
        else
            local pending = self.pendingByObject[record.object]
            if pending then self:_finish(pending) end
            self.discovery:_classify(record)
            local before = Discovery.serialize(record.object)
            if not before or not validEntry(entry or record.baseline) then
                callback(false, "The previous layout properties are unavailable.", skipped)
                return true
            end
            local raw, portable, problem = self:_savedFields(record, before, entry, previous[key],
                {delta = true, replace = true, experimental = true})
            if problem then callback(false, problem, skipped); return true end
            local operation = self:_operation(record, before, raw)
            operation.portable = portable
            operation.removeTracked = entry == nil
            operation.checkSize = raw.size ~= nil and not Util.equal(raw.size, record.baseline.size)
            if (entry and entry.experimental == true) ~= (previous[key] and previous[key].experimental == true) then
                operation.setApproval = entry and entry.experimental == true and "grant" or "revoke"
            end
            operation.receipt = entry and Util.copy(entry) or operation.after
            operations[#operations + 1] = operation
            if (entry and entry.opacity) or self.opacity:hasScope(record.key) or raw.transparency ~= nil then
                opacityEdits[#opacityEdits + 1] = {record = record, spec = entry and entry.opacity,
                    legacy = entry and entry.transparency ~= nil and entry.transparency or false}
            end
        end
    end
    local function complete(success, reason)
        if success then
            for _, key in ipairs(forgotten) do
                self.tracked[key] = nil
                self.opacity:forget(key)
            end
        end
        callback(success, reason, skipped)
    end
    if #operations == 0 then complete(true); return true end
    table.sort(operations, function(a, b) return #a.record.descriptor.path < #b.record.descriptor.path end)
    if #opacityEdits > 0 then
        local appearance, reason = self.opacity:prepare(opacityEdits)
        if reason then callback(false, reason, skipped); return true end
        operations[1].appearance = appearance
        for _, operation in ipairs(operations) do operation.appearanceExpected = appearance end
    end
    local ok, problem = self:_writeBatch(operations, true)
    if not ok then callback(false, problem, skipped); return true end
    local job = {operations = operations, replay = true, callback = complete}
    self.interactivePending = job
    self:_queue(job)
    return true
end

function Transform:_editProperties(keys, createEntry, capability, rootOnly)
    local operations, seen, failed = {}, {}, 0
    for _, key in ipairs(keys) do
        local record = self:_record(key, self.tracked[key])
        if record and seen[record.object] then
            -- Repeated keys or matched aliases refer to the same live target.
        elseif record and (not capability or self:_allowed(record, capability)) then
            local object = record.object
            seen[object] = true
            local previous = self.pendingByObject[object]
            if previous then self:_finish(previous) end
            local before = Discovery.serialize(object)
            if before then
                local after, portable, appearance = createEntry(record, before)
                if after and validEntry(portable or after) then
                    local operation = self:_operation(record, before, after)
                    operation.portable, operation.appearanceEdit = portable, appearance
                    operations[#operations + 1] = operation
                else failed = failed + 1 end
            else failed = failed + 1 end
        else failed = failed + 1 end
    end
    if rootOnly and #operations > 1 then
        local objects, byObject = {}, {}
        for _, operation in ipairs(operations) do
            local object = operation.record.object
            objects[#objects + 1], byObject[object] = object, operation
        end
        operations = {}
        for _, object in ipairs(Geometry.roots(objects, function(item) return item.Parent end)) do
            operations[#operations + 1] = byObject[object]
        end
    end
    if #operations == 0 then return 0, failed end
    local appearanceEdits = {}
    for _, operation in ipairs(operations) do
        if operation.appearanceEdit then appearanceEdits[#appearanceEdits + 1] = operation.appearanceEdit end
    end
    if #appearanceEdits > 0 then
        local appearance, reason = self.opacity:prepare(appearanceEdits)
        if reason then self.log(reason); return 0, failed + #operations end
        operations[1].appearance = appearance
        for _, operation in ipairs(operations) do operation.appearanceExpected = appearance end
    end
    if self.transaction or #appearanceEdits > 0 then
        if not self:_writeBatch(operations) then return 0, failed + #operations end
        if self.transaction then self:_recordUpdates(operations) end
        return #operations, failed
    end
    local applied = 0
    for _, operation in ipairs(operations) do
        if self:_writeBatch({operation}) then applied = applied + 1 else failed = failed + 1 end
    end
    return applied, failed
end

function Transform:setProperty(keys, property, value)
    if property ~= "rotation" and property ~= "transparency" then return 0, #keys end
    if not Util.finite(value) then return 0, #keys end
    return self:_editProperties(keys, function(record, before)
        if property == "transparency" and self.opacity:owns(record.object, "BackgroundTransparency") then return nil end
        local after = {[property] = value}
        local previous = self.tracked[record.key]
        local portable = portableEntry(record, before, previous)
        if not matchesProperty(before, after, property) or (previous and previous[property] ~= nil) then
            portable[property] = value
        end
        local appearance
        if property == "transparency" then appearance = {record = record, legacy = value, keep = true} end
        return after, portable, appearance
    end, property, property == "rotation")
end

function Transform:opacityOwnsBackground(key)
    local record = self.discovery:get(key)
    return record and self.opacity:owns(record.object, "BackgroundTransparency") or false
end

function Transform:canResetEntry(key, entry)
    local record = self:_record(key, entry)
    if not record or not record.object.Parent then return true end
    local before = Discovery.serialize(record.object)
    if not before then return false, "The original properties are unavailable." end
    self.discovery:_classify(record)
    local _, _, problem = self:_savedFields(record, before, nil, entry, {delta = true, replace = true})
    return problem == nil, problem
end

function Transform:resetRotation(keys)
    return self:_editProperties(keys, function(record, before)
        local portable = portableEntry(record, before, self.tracked[record.key])
        portable.rotation = nil
        return {rotation = record.baseline.rotation}, portable
    end, "rotation", true)
end

function Transform:restore(keys)
    local targets = keys
    if not targets then
        self:_supersedePending()
        targets = {}
        for key in pairs(self.tracked) do targets[#targets + 1] = key end
    end
    local restored, failed = self:_editProperties(targets, function(record, before)
        local previous = self.tracked[record.key]
        self.discovery:_classify(record)
        local after = self:_savedFields(record, before, nil, previous, {delta = keys == nil, replace = true})
        local portable = portableEntry(record, before, previous)
        if after.position then portable.position = after.position end
        if after.size then portable.size = after.size end
        for _, property in ipairs({"rotation", "transparency"}) do
            if after[property] and ((previous and previous[property] ~= nil) or not matchesProperty(before, after, property)) then
                portable[property] = after[property]
            end
        end
        if record.experimental then portable.experimental = record.experimentalApproved == true end
        portable.opacity = nil
        local appearance
        if self.opacity:hasScope(record.key) or after.transparency ~= nil then
            appearance = {record = record, legacy = portable.transparency or false}
        end
        return after, portable, appearance
    end, false)
    if failed > 0 then self.log(tostring(failed) .. " original elements unavailable during restoration") end
    return restored, failed
end

function Transform:matches(layout)
    local result = {}
    for key, entry in pairs(layout or {}) do
        if not self:_record(key, entry) then result[#result + 1] = {key = key, descriptor = Util.copy(entry.descriptor), reason = "No unique exact hierarchy match. Remap manually."} end
    end
    table.sort(result, function(a, b) return a.key < b.key end)
    return result
end

function Transform:clearTracked()
    self.tracked = {}
end

function Transform:destroy()
    self.destroyed, self.tracked, self.pendingByObject = true, {}, {}
    self.pendingStabilization, self.stabilizationScheduled, self.transaction, self.interactivePending = nil, false, nil, nil
    self.receipts = setmetatable({}, {__mode = "k"})
    self.opacity:destroy()
end

return Transform
end

