    end)
    self:section(body, "Behavior")
    self.preferenceFields.shortcut = self:labeledField(body, "Reopen shortcut", "F8", self.app.preferences.shortcut or "F8", function(v)
        local ok, key = pcall(function() return Enum.KeyCode[v] end)
